  Activity_116469_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_116470_ActivityName = {
    Text = "極晝的終夜"
  },
  Activity_116470_ActivityPlot = {
    Text = "他們在命運的盡頭擦肩而過，重新擺動的鐘錶已然遲到太久，只有那顆悔恨的心，發誓要將所有黑暗中的污穢全部照徹。"
  },
  Activity_116470_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「賜福儀式」"
  },
  Activity_116470_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「交融的苦血」、和「成就獎勵」收集活動貨幣「覲見奉禮」、「懺悔奉禮」、「忠誠奉禮」，「覲見奉禮」、「懺悔奉禮」、「忠誠奉禮」可在「賜福儀式」中購買商品，包括活動限定SR命輪「聖子尊容」、流明之芯、無垢之芯等。\n2、活動期間，「異夢視界：天邊之外·下」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：波呂克斯」！\n\n<Title:活動時間>\n1、10 月 20 日 9：00 - 11 月 3 日 9：00（GMT+8），所有活動玩法均可參與。\n2、11 月 3 日 9：00 - 11 月 10 日 9：00（GMT+8），僅可參與「賜福儀式」和成就獎勵。\n\n<Title:交融的苦血>\n1、「交融的苦血」包含 7 個關卡，每 1 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 回憶漩渦>\n·活動開始後，每小時自動獲得60「覲見奉禮」，最多儲存 25 小時。\n\n<Title: 賜福儀式>\n1、「賜福儀式」共有三個商店，開啟時間如下：\n·「濯洗肉身」： 10 月 20 日 9 時開啟。\n·「懺悔靈魂」： 10 月 21 日 9 時開啟。\n·「析出罪孽」： 10 月 22 日 9 時開啟。\n2、每次交換將消耗 750「覲見奉禮」/「懺悔奉禮」/「忠誠奉禮」，隨機獲得畫室中的五個物品獎勵。\n3、每個畫室的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「交融的苦血」關卡任務報酬中的「覲見奉禮」、「懺悔奉禮」、「忠誠奉禮」獲得額外的掉落加成，具體加成如下：\n·喚醒體「波呂克斯」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「扭曲的騎士詩」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「聖子尊容」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title:異夢視界>\n1、活動期間，「異夢視界：天邊之外·下」可免費解鎖。\n2、活動結束後，「異夢視界：天邊之外·下」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「異夢視界：天邊之外·下」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「異夢視界：天邊之外·下」後都可以獲得「鑰令：泣血的聖心」。"
  },
  Activity_116470_BannerText = {
    Text = "玩法活動限時開啟！"
