  Activity_116765_ActivityName = {
    Text = "銘刻的啟程"
  },
  Activity_116765_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「銘刻的啟程」中領取獎勵。\n2、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n3、本次「高級紀行」購買有時間限制，逾期將無法再購買。請守密人在 11 月 3日9：00前酌情購買。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_116765_BannerText = {
    Text = "特別紀行活動限時開啟！"
