  Activity_116818_ActivityName = {
    Text = "再戰原初"
  },
  Activity_116818_ActivityPlot = {
    Text = "「群星」是祂的眼睛，代替祂注視，或者說監視著世間的一切。\n你以為你逃脫了祂的視線，但事實是——你仍在祂的夢中。\n「抓住你了——」\n捕獲你的剎那，群星們發出了滿足的嘆息。"
  },
  Activity_116818_ActivityStageEndContent = {
    Text = "活動已結束"
  },
  Activity_116818_ActivityTips = {
    Text = "<Title: 再戰原初>\n·「再戰原初」包含 7 個不可重現、直接挑戰原初之視的關卡，活動前兩天開放 1 個，第三天開放 3 個，之後兩天每天開放 1 個。\n·每次挑戰戰勝對應的星辰原初之視後，即可獲得對應獎勵。\n·每種星辰原初之視均有大量分身，每當某個種類的星辰原初之視被任何守密人挑戰勝利時，該類型的「殘餘數量」就會減少 1，當該類型星辰原初之視被消滅後，相應的關卡就會關閉，無法再次挑戰。\n·每個關卡會提供不同的造物，將會為你提供強大的加成。\n·所有關卡必須選擇助戰，整個活動中，每個互相關注的守密人只能為你提供一次助戰。由於使用助戰，因此實際同調率獎勵會在獎勵基礎上再提高 50%。\n·每天每個喚醒體、命輪、鑰令只能出戰 1 次。\n·活動期間特遣紀錄「群星詠嘆調」免費解鎖開啟且無需前置條件！玩法活動「再戰原初」結束後，需要先完成「調查行動-星辰篇-第四章」才能開啟特遣紀錄「群星詠嘆調」。\n\n<Title: 等級補償>\n·在「再戰原初」中有等級補償機制，以便各位守密人能夠並肩作戰！\n等級補償規則如下：\n  ·調查隊伍中，等級不足 60 級的喚醒體在本次挑戰中將會補償至 60 級。\n  ·調查隊伍中，技能等級不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n  ·調查隊伍中，「瘋狂預兆」不足 6 級的喚醒體在本次挑戰中將會補償至 6 級。\n  ·調查隊伍中，「靈塑適性」不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n  ·若守密人等級不足60級，在本次挑戰中將會補償至60級。\n\n<Title:特遣紀錄>\n·活動期間，「特遣紀錄：群星詠嘆調」可免費解鎖開啟且無需前置條件！\n·活動結束後，「特遣紀錄：群星詠嘆調」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「特遣紀錄：群星詠嘆調」，活動結束後需要先完成「調查行動-星辰篇-第四章」並消耗「現實起點」×7 才能開啟特遣紀錄「群星詠嘆調」。\n·無論是否在活動期間，通關「特遣紀錄：群星詠嘆調」後都可以獲得「鑰令：重逢心願」。"
  },
