    Text = "完成任務後可從以下限定喚醒體中選擇1名喚醒！"
  },
  Activity_119693_ActivityTips = {
    Text = "<Title:活動規則>\n·活動期間，每位守密人累計使用 200 次鑰令後，可以從 8 名限定SSR喚醒體中選擇 1 名喚醒，包括熔毀·朵爾、克萊門汀、克珀珊特、卡斯托爾、杜勒賽因、凱蒂古拉、皮克曼、波呂克斯。\n·當守密人選擇已喚醒的喚醒體時，第 2~16 次獲得相同SSR喚醒體時，每次將轉換為 1 個對應喚醒體的殘片和「根源沉澱」× 50；第 17 次及之後獲得，限定SSR喚醒體將轉換為「精粹靈核碎片」× 2、「靈核碎片」× 6 和「根源沉澱」× 250。"
  },
