  Activity_122195_ActivityName = {
    Text = "霧境的燔禮"
  },
  Activity_122195_ActivityPlot = {
    Text = "黎明的光正消解虔者之苦，繁星作舟，將兄弟姐妹載至高懸的國度。\n迷失的羔羊在門中歌舞，星燭裝點著永恆的神庭。\n可門後的迷霧早已應呼喚而來，那迷霧欺瞞、詭騙，只為滿足自己扭曲的趣味。\n那迷霧為此將「黎明」封鎖，阻絕了嘗試解脫的路。\n她將在此，見證世界的又一次盡頭。"
  },
  Activity_122195_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「茉夏的小屋」"
  },
  Activity_122195_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「迷失的自我」和「成就獎勵」收集活動貨幣「迷霧之視」、「迷霧之夢」、「迷霧之源」，「迷霧之視」、「迷霧之夢」、「迷霧之源」可在「茉夏的小屋」中購買商品，包括活動限定SR命輪「理智明燈」、流明之芯、無垢之芯等。\n2、活動期間，「多維連接：銀與血的洗禮」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：茉夏」！\n\n<Title:活動時間>\n1、12 月 29 日 9：00 - 1 月 12 日 9：00（GMT+8），所有活動玩法均可參與。\n2、1 月 12 日 9：00 - 1 月 19 日 9：00（GMT+8），僅可參與「茉夏的小屋」和成就獎勵。\n\n<Title:迷失的自我>\n1、「迷失的自我」包含 7 個關卡，每 1 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 茉夏的小屋>\n「茉夏的小屋」共有三個商店，開啟時間如下：\n·「材料室」： 12 月 29 日 9 時開啟。\n·「入夢室」： 12 月 30 日 9 時開啟。\n·「培養室」： 12 月 31 日 9 時開啟。\n在商店內可以選擇商品直接進行購買。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「迷失的自我」關卡任務報酬中的「迷霧之視」、「迷霧之夢」、「迷霧之源」獲得額外的掉落加成，具體加成如下：\n·喚醒體「茉夏」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「狂戮至世界盡頭」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「理智明燈」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title:多維連接>\n1、活動期間，「多維連接：銀與血的洗禮」可免費解鎖。\n2、活動結束後，「多維連接：銀與血的洗禮」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「多維連接：銀與血的洗禮」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「多維連接：銀與血的洗禮」後都可以獲得「鑰令：來自霧境」。"
  },
  Activity_122195_BannerText = {
    Text = "玩法活動限時開啟！"
