  Activity_122520_ActivityName = {
    Text = "雨鎮幽影·復刻"
  },
  Activity_122520_ActivityPlot = {
    Text = "那場朦朧又潮濕的夜雨中，有一場注定的相逢在等待你。\n你記得她的名字，熟悉她的樣貌， 那和緩而優雅的嗓音總讓你如此安心。\n只是你忘了，樂於滿足人類願望的，從來只有神明與魔鬼。\n猜一猜，她屬於哪一個？"
  },
  Activity_122520_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「魔女的寶庫」"
  },
  Activity_122520_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「魔女小店」和「成就獎勵」收集活動貨幣，活動貨幣可在「魔女的寶庫」中用於交換從而獲得道具獎勵，包括活動限定SR命輪「魔女寬簷帽」、賢者之石、無垢之芯、流明之芯等。\n2、活動期間「特遣紀錄：雨鎮幽影」將免費開放，完成活動成就還能獲得活動限定頭像「以銀鑰之名：達芙黛爾」！。\n\n<Title:活動時間>\n1、1 月 12 日 9：00 - 1 月 26 日 9：00（GMT+8），所有活動內容均可參與。\n2、1 月 26 日 9：00 - 2 月 2 日 9：00（GMT+8），僅保留「魔女的寶庫」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 魔女小店>\n1、「魔女小店」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title: 活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「魔女小店」關卡任務報酬中的「蒼白野獸頭骨」、和「幽影野獸頭骨」「殷紅野獸頭骨」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「達芙黛爾」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「至為珍貴的藏品」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「魔女寬簷帽」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title: 魔女的寶庫>\n1、「魔女的寶庫」共有三個，開啟時間如下：\n·「解憂佳品」： 1 月 12 日 9：00 - 2 月 2 日 9：00。\n·「瑰麗秘寶」： 1 月 14 日 9：00 - 2 月 2 日 9：00。\n·「珍藏奇貨」： 1 月 16 日 9 時 - 2 月 2 日 9：00。\n2、每次交換將消耗 750「蒼白野獸頭骨」/「幽影野獸頭骨」/「殷紅野獸頭骨」，隨機獲得寶庫中的五個物品獎勵。\n3、每個寶庫的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使指定物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 2 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 3 次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title: 特遣紀錄>\n1、活動期間「特遣紀錄：雨鎮幽影」將免費開放。\n2、活動結束後，「特遣紀錄：雨鎮幽影」的調查進度會保留，如果活動期間未解鎖「特遣紀錄：雨鎮幽影」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「特遣紀錄：雨鎮幽影」後都可以獲得「鑰令：灰霧真容」。"
  },
