  Activity_124051_ActivityName = {
    Text = "沉淵之祀·復刻"
  },
  Activity_124051_ActivityPlot = {
    Text = "深海的倒影上，王的夢境消散，神的國度也已腐朽。\n她從舊日的幻夢中走來，走入未來坍塌的廢墟。\n她詢問深淵，深淵緘默不語。\n她向深淵祭祀，回應她的，只有她自己。"
  },
  Activity_124051_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「沉淵的回應」"
  },
  Activity_124051_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間、守密人可透過限時玩法「神國誕臨」、「王的聖旨」和「成就獎勵」收集活動貨幣、活動貨幣可在「沉淵的回應」中用於進獻從而獲得道具獎勵、包括活動限定SR命輪「深海的呼喚」、賢者之石、無垢之芯、流明之芯等。\n2、活動期間「異夢視界：褻瀆」將免費開放、完成活動成就還能獲得活動限定頭像「以銀鑰之名：彌利亞姆」！。\n\n<Title:活動時間>\n1、3 月 9 日 9：00 - 3 月 23 日 9：00（UTC+8）、所有活動內容均可參與。\n2、3 月 23 日 9：00 - 3 月 30 日 9：00（UTC+8）、僅保留「沉淵的回應」和「成就獎勵」、其他內容均已結束不可參與。\n\n<Title: 神國誕臨>\n1、「神國誕臨」包含 5 個關卡、每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 、挑戰成功將獲得活動貨幣。\n3、關卡通關後、解鎖該關卡的「重現」功能。請注意：使用「重現」功能時、無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：海淵祭儀」來幫助你更輕鬆地通關。\n\n<Title:祀物加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「神國誕臨」關卡任務報酬中的「祀者之淚」、「祀者之血」和「祀者之髓」獲得額外的掉落加成（包括重現）、具體加成如下：\n·喚醒體「彌利亞姆」：啟靈0/1/2/3及以上、加成20%/30%/40%/50%\n·SSR命輪「虔誠的偉力」：疊位0/1/2/3及以上、加成20%/30%/40%/50%\n·SR命輪「深海的呼喚」：疊位0/1/2/3及以上、加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「祀物加成」以疊加的方式結算。 \n3、特別的、癲狂難度首通挑戰獎勵不會受到「祀物加成」影響。\n\n<Title:共鳴：海淵祭儀>\n1、守密人可以透過完成活動成就獲取「虔信之心」。 \n2、消耗「虔信之心」、激活「共鳴：海淵祭儀」、可以獲得以下加成：\n（1）讓守密人在活動玩法「神國誕臨」中變得更強、挑戰更加輕鬆。\n（2）提升完成「神國誕臨」挑戰後獲得的活動貨幣。\n（3）激活活動玩法「王的聖旨」。\n\n<Title:王的聖旨>\n·激活共鳴「祭獻試煉」後、每小時自動獲得60「祀者之淚」、最多儲存 25 小時。\n\n<Title:沉淵的回應>\n1、「沉淵的回應」共有三個祭壇、開啟時間如下：\n·「瑩淚祭壇」： 3 月 9 日 9 時 ~ 3 月 30 日 9 時。\n·「猩血祭壇」： 3 月 11 日 9 時 ~ 3 月 30 日 9 時。\n·「靈髓祭壇」： 3 月 13 日 9 時 ~ 3 月 30 日 9 時。\n2、每次進獻祭品將消耗「祀者之淚」/「祀者之血」/「祀者之髓」× 750、隨機獲得祭壇中的五個物品獎勵。\n3、每個祭壇的物品獎勵分為「特殊物品」和「普通物品」兩種、重置時可以使指定物品獎勵的剩餘數量重置至上限、具體規則為：\n（1）前3次重置：當「特殊物品」無剩餘數量後、守密人可以選擇重置、重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續進獻祭品、當「普通物品」也無剩餘數量後、須進行重置才可以繼續進獻祭品。\n（2）第4次開始重置：當「普通物品」無剩餘數量後才可以進行重置、重置會將「普通物品」的剩餘數量重置至上限、「特殊物品」不再重置。\n\n<Title:異夢視界>\n1、活動期間「異夢視界：褻瀆」將免費開放。\n2、活動結束後、「異夢視界：褻瀆」的調查進度會保留、如果活動期間未解鎖「異夢視界：褻瀆」、活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間、通關「異夢視界：褻瀆」後都可以獲得「鑰令：海之祭」。\n\n<Title:復刻補償>\n1、此前已經解鎖「異夢視界：褻瀆」的守密人、在本次復刻活動期間重新解鎖時將會獲得「祀者之淚」×700的補償。\n2、此前已經獲得活動限定頭像「以銀鑰之名：彌利亞姆」的守密人、重複獲得時將自動轉換為「無形者的請柬」×1。\n3、此前已經獲得激活共鳴材料「虔信之心」的守密人、每獲得 1 個多餘的「虔信之心」將自動轉換為「薔薇金券」×5000。\n"
  },
