  Activity_124801_ActivityPlot = {
    Text = "“我要讓所有人都玩萬象牌！”\n其他時空的來客因為一場意外進入了相位對弈的空間，將其改造成了與原先大不相同的樣子。\n為了將空間再次逆轉，不同時空的守密人將要決出一位最強者，向這名來客發起挑戰。"
  },
  Activity_124801_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過參與「相位對弈」來完成「成就獎勵」中的成就，並領取「魔法橡果」。\n2、「魔法橡果」可以在「回合奇賞」中領取豐富的獎勵，包括活動限定頭像「逆轉回合：萬象牌」、10個活動限定表情，以及「碎裂餘夢」、「群星餘夢」等。\n3、活動期間「多維連接：逆轉回合」將免費開放！\n4、活動期間，通關了「多維連接：逆轉回合：來自異界的客人」的守密人，「相位對弈」對戰背景會限時替換為「逆轉回合：意識空間」。\n\n<Title: 成就獎勵>\n1、「成就獎勵」中包含了「秘儀試煉」、「榮勳試煉」、「閾限試煉」，守密人可以透過完成成就目標領取「魔法橡果」。\n2、在「秘儀試煉」成就中\n·每擊敗 3 名對方喚醒體即可獲得「魔法橡果」× 10，最多可以完成 50 次。\n·每釋放 6 次狂氣爆發即可獲得「魔法橡果」× 10，最多可以完成 50 次。\n·每打出 20 張卡牌即可獲得「魔法橡果」× 10，最多可以完成 50 次。\n3、核心課題臨時解鎖的「喚醒體」、「命輪」、「鑰令」將會正常進行「成就獎勵」計數。友誼賽與密碼對弈無法進行「成就獎勵」計數。\n\n<Title: 回合奇賞>\n1、守密人累積「魔法橡果」即可領取對應獎勵，累積「魔法橡果」× 3600 能夠獲得全部核心獎勵，累積「魔法橡果」× 6000 就可以獲得所有獎勵！\n2、通關「逆轉回合：來自異界的客人」後解鎖積累 100-900「魔法橡果」的獎勵，通關「逆轉回合：逆轉萬象的瞬間」後解鎖積累 1000-6000「魔法橡果」的獎勵。\n\n<Title: 多維連接>\n1、活動期間「多維連接：逆轉回合」將免費開放。\n2、活動結束後，「多維連接：逆轉回合」的調查進度會保留，如果活動期間未解鎖「多維連接：逆轉回合」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「多維連接：逆轉回合」後都可以獲得「鑰令：酒館之門」。\n\n<Title:活動時間>\n本次活動僅在3 月 16 日 9：00 - 3 月 30 日 9：00（GMT+8）期間開放，3 月 30 日 9：00（GMT+8）後活動結束，請各位守密人記得領取「回合奇賞」中的獎勵哦！"
  },
  Activity_124801_BannerText = {
    Text = "特別活動限時開啟！"
  },
  Activity_124801_UnlockConditionExplanation = {
    Text = "完成「調查行動」3-2·普通 後解鎖"
  },
  Activity_124834_ActivityName = {
    Text = "因霧之名"
  },
  Activity_124834_ActivityPlot = {
    Text = "忘卻前夜 × 霧境序列\n聯動特別邀約\n\n「茉夏，調查團……哦不，現在已經不是調查團前鋒了。那麼，我再重新介紹一下自己——我叫茉夏，只是一個可愛的女孩子~」"
  },
  Activity_124834_ActivityTips = {
    Text = "<Title:活動規則>\n·在「因霧之名」活動期間完成調查行動第一章「東區秘事」後，可以免費獲得全新限定SSR喚醒體「茉夏」！\n·當第 2~16 次獲得相同SSR喚醒體時，每次將轉換為 1 個對應喚醒體的殘片和「根源沉澱」× 50；第 17 次及之後獲得，限定SSR喚醒體將轉換為「精粹靈核碎片」× 2、「靈核碎片」× 6 和「根源沉澱」× 250。"
  },
  Activity_124834_BannerText = {
    Text = "限定喚醒體免費領取"
  },
  Activity_124981_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_124982_ActivityTips = {
    Text = "<Title:活動規則>\n·「分裂患者·混沌」活動開啟期間，守密人可使用包含「24」的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_124983_ActivityTips = {
    Text = "<Title:活動規則>\n·「分裂患者·血肉」活動開啟期間，守密人可使用包含「24」的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
