  Activity_124987_ActivityName = {
    Text = "多重療癒·復刻"
  },
  Activity_124987_ActivityPlot = {
    Text = "Hysteria，又名歇斯底里症、癔症。\n在你們身處的年代，它與死亡同義。\n\n幸運的是，彌薩格的科學家和調查員同樣瘋狂：他們決心攻克這一難題。"
  },
  Activity_124987_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「人格解析」"
  },
  Activity_124987_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「記憶編碼」、「邊緣存儲」和「成就獎勵」收集活動貨幣「記憶拼圖」，「記憶拼圖」可在「人格解析」中購買商品，包括活動限定SR命輪「銀鱈魚的決心」、流明之芯、無垢之芯等。\n2、活動期間，「特遣紀錄：寧靜的裂殖」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：」24「」！\n\n<Title:活動時間>\n1、2 月 23 日 9：00 - 3 月 9 日 9：00（GMT+8），所有活動玩法均可參與。\n2、3 月 9 日 9：00 - 3 月 16 日 9：00（GMT+8），僅可參與「人格解析」和成就獎勵。\n\n<Title:記憶編碼>\n1、「記憶編碼」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：分離性症候」來幫助你更輕鬆地過關。\n\n<Title:理性加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「記憶編碼」關卡任務報酬中的「記憶拼圖」獲得額外的掉落加成，具體加成如下：\n·喚醒體「24」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「畸體回噬」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「銀鱈魚的決心」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「理性加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「理性加成」影響。\n\n<Title:共鳴：分離性症候>\n1、守密人可以透過完成活動成就獲取「分裂之心」。 \n2、消耗「分裂之心」，啟動「共鳴：分離性症候」，可以獲得以下加成：\n（1）讓守密人在活動玩法「記憶編碼」和「特遣紀錄：寧靜的裂殖」中變得更強，挑戰更加輕鬆。\n（2）提升完成「記憶編碼」挑戰後獲得的獎勵。\n（3）啟動活動玩法「邊緣存儲」。\n\n<Title: 邊緣存儲>\n1、啟動共鳴「診斷：人格分裂」後，每小時自動獲得「記憶拼圖α」× 60，最多儲存 25 小時。\n2、啟動共鳴「認知同調」後，每小時自動獲得「記憶拼圖β」× 30，最多儲存 25 小時。\n\n<Title:特遣紀錄>\n1、活動期間，「特遣紀錄：寧靜的裂殖」可免費解鎖。\n2、活動結束後，「特遣紀錄：寧靜的裂殖」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「特遣紀錄：寧靜的裂殖」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「特遣紀錄：寧靜的裂殖」後都可以獲得「鑰令：全部的她」。\n\n<Title:復刻補償>\n1、此前已經解鎖「特遣紀錄：寧靜的裂殖」的守密人，在本次復刻活動期間重新解鎖時將會獲得「記憶拼圖α」×700的補償。\n2、此前已經獲得活動限定頭像「以銀鑰之名：」24「」的守密人，重複獲得時將自動轉換為「無形者的請柬」×1。\n3、此前已經獲得啟動共鳴材料「分裂之心」的守密人，每獲得 1 個多餘的「分裂之心」將自動轉換為「薔薇金券」×5000。\n"
  },
  Activity_124987_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_124988_ActivityTips = {
    Text = "<Title:活動規則>\n·「索魂者」活動開啟期間，守密人可使用包含血鏈·希洛的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_125364_ActivityName = {
    Text = "海城舊聞"
  },
  Activity_125364_ActivityPlot = {
    Text = "權力、愛慾、紙醉金迷，深宅中屍身橫陳的祭案上，古老的存在緩緩睜開了眼睛。\n啊，但這並不是一個可怕的故事，祂「愛」你，祂會永遠「保護」你……祂要把所有「最好的」，都交予你。"
  },
  Activity_125364_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「荒宅野奉」"
  },
  Activity_125364_ActivityTips = {
    Text = "<Title:活動簡介>\n活動期間，守密人可透過限時玩法「玄女無相」和「成就獎勵」收集活動貨幣「梨膏糖」，「梨膏糖」可在「荒宅野奉」中換取獎勵，包括活動限定SR命輪「玉蘭之餌」、流明之芯、無垢之芯、賢石碎屑、擬態凝晶等。\n\n<Title:玄女無相>\n1、「玄女無相」包含 9 個無需探索直接戰鬥的素材關卡，每天開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得培養素材和活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「玄女無相」關卡任務報酬中的「梨膏糖」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「徐」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「枉蹙眉」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「玉蘭之餌」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title: 荒宅野奉>\n1、每次「供奉」將消耗 750「梨膏糖」，隨機獲得「荒宅野奉」中的五個物品獎勵。\n2、「荒宅野奉」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 5 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 6 次及之後重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:意識潛遊>\n1、活動期間，「扇下夜談」可免費解鎖。\n2、活動結束後，「扇下夜談」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「扇下夜談」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「意識潛遊：扇下夜談」後都可以獲得「鑰令：深宅往事」。\n\n<Title:活動時間>\n1、1 月 26 日 9：00 - 2 月 9 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、2 月 9 日 9：00 - 2 月 16 日 9：00（GMT+8），僅保留「荒宅野奉」和「成就獎勵」，其他內容均已結束不可參與。\n3、2 月 16 日 9：00（GMT+8）後，剩餘未兌換的「梨膏糖」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
