    Text = "紡輪輕轉，亙古不停。沿著絲線起舞吧，偉大的編織者。命運，是你無法逃離的舞台。\n審判者。救贖者。主人。囚徒……\n在踏入這座舞台之時，屬於你的角色，早已無從選擇。"
