  },
  Activity_126275_ActivityTips = {
    Text = "<Title:活動簡介>\n活動期間，守密人可透過限時玩法「木偶的舞台」和「成就獎勵」收集活動貨幣「絲絨座票根」，「絲絨座票根」可在「劇院禮品店」中兌換獎勵，包括活動限定SR命輪「宿命紡輪」、流明之芯、無垢之芯、賢石碎屑、擬態凝晶等。\n\n<Title:木偶的舞台>\n1、「木偶的舞台」包含 5 個無需探索直接戰鬥的素材關卡，每 2 天開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得培養素材和活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「木偶的舞台」關卡任務報酬中的「絲絨座票根」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「阿拉克涅」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「永世編織之網」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「宿命紡輪」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title: 劇院禮品店>\n1、每次「禮品兌換」將消耗 750「絲絨座票根」，隨機獲得「劇院禮品店」中的五個物品獎勵。\n2、「劇院禮品店」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 5 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 6 次及之後重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動時間>\n1、4 月 20 日 9：00 - 5 月 18 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、5 月 18 日 9：00 - 5 月 25 日 9：00（GMT+8），僅保留「劇院禮品店」和「成就獎勵」，其他內容均已結束不可參與。\n3、5 月 25 日 9：00（GMT+8）後，剩餘未兌換的「絲絨座票根」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
  Activity_126275_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_126365_ActivityName = {
    Text = "命縷紀行"
  },
  Activity_126365_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「命縷紀行」中領取獎勵。\n2、「命縷紀行」永久開放。\n3、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_126366_ActivityName = {
    Text = "歷程追思獻禮·星辰篇Ⅴ"
  },
  Activity_126366_ActivityPlot = {
    Text = "一段記憶塵封歸檔，一段歷程載入過往。追思之時，勿忘獻上崇敬之禮。"
  },
  Activity_126492_ActivityName = {
    Text = "古國雜俎"
  },
  Activity_126492_ActivityTips = {
    Text = "<Title: 古國雜俎>\n·本次限時紀行包含 8 個禮包，其中首個禮包可直接免費領取，第 2-8 個禮包需要購買「古國雜俎」後方可領取。\n·購買「古國雜俎」後可立即領取第 2 個禮包獎勵；後續禮包需要分別等待一定時間後才可領取。\n·在 1 月 26 日 9：00 前購買「古國雜俎」還可額外獲得獎勵：專屬頭像「扇中真形」、「無形者的請柬」×10！在 1 月 26 日 9：00 後購買將不再獲得限時專屬獎勵。 \n· 購買後，本次限時紀行的持續時間將會變為永久，當領取完所有的禮包後次日活動關閉。\n·「古國雜俎」購買有時間限制，逾期將無法再購買。請守密人在 2 月 23 日 9：00 前酌情購買。"
  },
  Activity_126492_BannerText = {
    Text = "特別紀行活動限時開啟！"
  },
  Activity_127173_ActivityName = {Text = "繪者"},
  Activity_127173_ActivityTips = {
    Text = "<Title:活動規則>\n·「繪者」活動開啟期間，守密人可使用包含皮克曼的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_129488_ActivityName = {
    Text = "疾馳的歡愉專列"
  },
  Activity_129488_ActivityPlot = {
    Text = "列車上，煩躁的咆哮聲不斷從雅室傳出。\n「薩爾瓦多，第三節車廂需要支援！」\n「旺達，把你控制的敵人派去車尾，它們追上來了！」\n「萊克！別搭訕了！快來把我窗外的傢伙趕走！」\n正在豪華包廂焦頭爛額的你，完全沒留意到，一個小小的身影，已經偷偷潛入了你的口袋。\n「嘻嘻，果然要這樣才有趣。」\n「拍下了不錯的影像嘛~那麼接下來——該幫手小」N「出場了~ 」"
  },
  Activity_129488_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過「專列軌跡」來獲取豐富的限時獎勵，活動結束後「專列軌跡」中的獎勵將無法再領取，請各位守密人及時領取限時獎勵。\n2、活動期間，參與「列車啟程」會獲得等級補償，具體規則如下：\n ·調查隊伍中，等級不足 60 級的喚醒體在本次挑戰中將會補償至 60 級。\n ·調查隊伍中，技能等級不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n ·調查隊伍中，「瘋狂預兆」不足 6 級的喚醒體在本次挑戰中將會補償至 6 級。\n ·調查隊伍中，「靈塑適性」不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n ·若守密人等級不足60級，在本次挑戰中將會補償至60級。\n\n<Title:特遣紀錄>\n1、活動期間「特遣紀錄：開往祈歲節的列車」將免費開放。\n2、活動結束後，「特遣紀錄：開往祈歲節的列車」的調查進度會保留，如果活動期間未解鎖「特遣紀錄：開往祈歲節的列車」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「特遣紀錄：開往祈歲節的列車」後都可以獲得「鑰令：歲末花火」。\n\n<Title:疾馳的歡愉專列>\n1、「疾馳的歡愉專列」是採用「星辰篇」規則的連續挑戰模式。守密人將在多變的隨機遭遇中連續挑戰多個調查行動中出現過的最終首領！\n2、玩法中造物持有上限最高可提升至 36 個。\n3、挑戰過程中可同時擁有並強化 3 種調查行動中的強大「共鳴」效果。\n4、每使用 1 次應急靈知體，會減少 20% 本次挑戰獲取的「貴賓積分」。\n5、支援中途退出並保留進度，但隊伍狀態不會隨外部養成變化同步更新。進度至多保留至上一次挑戰的 7 天後，若保留期間沒有繼續挑戰則視為放棄挑戰，進度不再保留。\n\n<Title:貴賓名錄>\n1、活動期間，「貴賓名錄」中的記錄將會保留，活動結束後會跟隨學園活動的週期重置記錄。\n2、「貴賓名錄」會記錄挑戰表現優異的守密人，每期學園活動期間挑戰 1 次，並且成功獲得「貴賓積分」的守密人即可進入「貴賓名錄」。\n3、「貴賓名錄」的排名會以單次挑戰獲得最多的「貴賓積分」和所用最少的「回合數」為依據，可重複挑戰以提高排名。\n\n<Title:活動時間>\n1、2 月 9 日 9：00 - 3 月 9 日 9：00（GMT+8），所有活動內容均可參與。\n2、3 月 9 日 9：00 （GMT+8）後，活動將會被收錄至「記憶迴廊」，「專列軌跡」中的獎勵將無法再領取。"
  },
