  Activity_130175_ActivityName = {
    Text = "顛倒的新生"
  },
  Activity_130175_ActivityPlot = {
    Text = "世界實在太過寂寥，世界實在太過荒蕪，請傾聽吧，請見證吧。\n嘶鳴的血肉在長久的靜默中等待，等待蒲公英在沙漠中盛開。\n然後它將被閃耀著光輝的愛意填滿，再度獲得新生。"
  },
  Activity_130175_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「蒲公英園圃」"
  },
  Activity_130175_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可通過限時玩法「暗室手記」和「成就獎勵」收集活動貨幣「純白鱗粉」「紅色鱗粉」「耀光鱗粉」，並在「蒲公英園圃」中兌換商品，包括活動限定SR命輪「淤泥裡的童話」、流明之芯、無垢之芯等。\n2、活動期間，「多維連結：被遺忘的愛之種」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：沙耶」！\n\n<Title:活動時間>\n1、5 月 30 日 9：00 - 8 月 24 日 9：00（UTC+8），所有活動玩法均可參與。\n2、8 月 24 日 9：00 - 8 月 31 日 9：00（UTC+8），僅可參與「蒲公英園圃」和成就獎勵。\n\n<Title:暗室手記>\n1、「暗室手記」包含 7 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 蒲公英園圃>\n1、「蒲公英園圃」共有三個商店，開啟時間如下：\n·「育種園圃」： 5 月 30 日 9 時開啟。\n·「生長園圃」： 5 月 31 日 9 時開啟。\n·「盛開園圃」： 6 月 1 日 9 時開啟。\n2、每次交換將消耗「純白鱗粉」/「紅色鱗粉」/「耀光鱗粉」× 750，隨機獲得「蒲公英園圃」中的五個物品獎勵。\n3、每個「蒲公英園圃」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「暗室手記」關卡任務報酬中三種活動貨幣的掉落獲得額外加成：\n·喚醒體「沙耶」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「願世界化作芬芳」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「淤泥裡的童話」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、多項「活動加成」可疊加計算。 \n3、注意，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title:多維連結>\n1、活動期間，「多維連結：被遺忘的愛之種」可免費解鎖。\n2、活動結束後，調查進度將保留，活動期間未完成的調查事件在活動後繼續完成同樣可獲得對應獎勵。如活動期間未解鎖，活動結束後仍可消耗「現實起點」× 3 解鎖。\n3、無論是否在活動期間，通關「多維連結：被遺忘的愛之種」均可獲得「鑰令：獻給新世界」。"
  },
