  Activity_131849_ActivityName = {
    Text = "永恆的記憶"
  },
  Activity_131849_ActivityTips = {
    Text = "<Title: 永恆的記憶>\n·本次限時紀行包含 8 個禮包，其中首個禮包可直接免費領取，第 2-8 個禮包需要購買「永恆的記憶」後方可領取。\n·購買「永恆的記憶」後可立即領取第 2 個禮包獎勵；後續禮包需要分別等待一定時間後才可領取。\n·在 5 月 30 日 9：00 前購買「永恆的記憶」還可額外獲得獎勵：專屬頭像「愉快的獵食」、「無形者的請柬」×10！在 5 月 30 日 9：00 後購買將不再獲得限時專屬獎勵。\n·「永恆的記憶」購買有時間限制，逾期將無法再購買。請守密人在 6 月 29 日 9：00 前酌情購買。"
  },
