  Activity_132333_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「覺知海淵」"
  },
  Activity_132333_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可以透過限時玩法「深海凝視」和「成就獎勵」收集活動貨幣「憊倦緒思」、「悲愁緒思」、「歡悅緒思」。活動貨幣可在「覺知海淵」中購買商品，包括活動限定SR命輪「青石王座」、流明之芯、無垢之芯、賢石碎屑、擬態凝晶等。\n2、活動期間，完成活動成就還能獲得活動限定頭像「以銀鑰之名：圖魯」、活動限定SR命輪「青石王座」、銀芯和大量活動貨幣！\n\n<Title:活動時間>\n1、4 月 6 日 9：00 - 5 月 4 日 9：00（GMT+8），所有活動玩法均可參與。\n2、5 月4 日 9：00 - 5 月 11 日 9：00（GMT+8），僅可參與「覺知海淵」和成就獎勵。\n\n<Title:深海凝視>\n1、「深海凝視」有 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗「靈啡肽」× 120，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title:緒思加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「深海凝視」關卡任務報酬中的活動貨幣獲得額外的掉落加成，具體加成如下：\n·喚醒體「圖魯」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「神王的頌歌」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「青石王座」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「緒思加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「緒思加成」影響。\n\n<Title: 覺知海淵>\n1、「覺知海淵」僅在 4 月 6 日 9：00 - 5 月 11 日 9：00（GMT+8）期間開放。\n2、5 月 11 日 9：00（GMT+8）後，剩餘未兌換的「憊倦緒思」、「悲愁緒思」、「歡悅緒思」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。\n\n<Title:意識潛游>\n1、活動期間，「意識潛游：加冕之日」可免費解鎖。\n2、活動結束後，「意識潛游：加冕之日」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「意識潛游：加冕之日」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「意識潛游：加冕之日」後都可以獲得「鑰令：群星的庇佑」。\n\n<Title:復刻補償>\n1、此前已經解鎖「意識潛游：加冕之日」的守密人，在本次復刻活動期間重新解鎖時將會獲得「憊倦緒思」×300的補償。\n2、此前已經獲得活動限定頭像「以銀鑰之名：圖魯」的守密人，重複獲得時將自動轉換為「無形者的請柬」×1。"
  },
