  Activity_132688_ActivityTips = {
    Text = "<Title:活動簡介>\n 1、守密人完成活動指定任務後，可領取「流明之芯」、活動限定頭像「溫柯爾·大型終端」、「艾瑞卡·便攜終端」及「典藏郵票：守密人」，更有全新 1 星幻衣「諾締拉·螺紋回音」、「希洛·破縛時刻」等活動限定獎勵！ \n 2、本活動永久開放。完成活動中所有任務並領取完獎勵後，第二天9：00（UTC+8）後本活動結束並不再展示。\n 3、若此前已在登入獎勵功能中完成過「使用PC設備登入」或「使用移動設備登入」任務，則此處不會重複計為完成。"
