  Activity_133272_ActivityPlot = {
    Text = "一個偉大的時代或許終究會消亡，但那些偉大勇士的意志永遠不會消亡。\n墓碑無法掩埋他們，鎖鏈無法馴服他們。\n當新的征途出現，美味的烤肉在那征服之路的盡頭招手，戰士們發起衝鋒，將那榮耀的戰利品收入囊中。\n讓我們為這不滅的英勇，為這神聖的帝國高歌！\n羅馬！羅馬！"
