  Activity_139116_ActivityName = {
    Text = "宛如夢幻的相逢"
  },
  Activity_139116_ActivityTips = {
    Text = "<Title:活動規則>\n·守密人完成指定的紀行任務後，可以在「宛如夢幻的相逢」中領取獎勵。\n·解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n·本次「高級紀行」購買有時間限制，逾期將無法再購買。請守密人在 6 月 29 日9：00（GMT+8）前酌情購買。\n·請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_139116_BannerText = {
    Text = "免費領取全新限定喚醒體！"
  },
  Activity_139117_ActivityName = {
