  },
  Activity_139591_ActivityName = {
    Text = "貓的「報恩」"
  },
  Activity_139591_ActivityPlot = {
    Text = "「緊急通知，請全校師生立刻結束現有工作，協助抓捕出逃實驗體。」\n「重複一遍，請全校師生立刻結束現有工作，協助抓捕出逃……該死！這些貓進來了！」\n當你聽到廣播中慌亂的聲音時，整個校園已經被黑色絨毛淹沒，大家正手忙腳亂地抓捕這些逃出實驗室的小壞蛋。\n似乎是為了報祈歲節的仇，這些黑貓正緩慢而有序地向你的宿舍匯聚。\n不過嘛……考慮到牠們攜帶的大量金券和銀芯，你很難說牠們是來報仇的，還是來「報恩」的。\n注意，不要過度捕撈哦。"
  },
  Activity_139591_ActivityStageEndContent = {
    Text = "活動已結束"
  },
  Activity_139591_ActivityTips = {
    Text = "<Title: 貓的「報恩」>\n·貓的「報恩」包含 7 個不可重現、直接挑戰的關卡，活動每天開放 1 關。\n·每次挑戰戰勝對應的「維度黑貓」後，即可累積任務進度，在「黑貓抓捕記錄」中領取相應獎勵。\n·每種「維度黑貓」均有大量分身，活動期間可以不限次數的參與挑戰，挑戰支援自動戰鬥。\n·每個關卡會提供不同的造物，將會為你提供強大的加成。\n·所有關卡必須選擇助戰，整個活動中，每個互相關注的守密人只能為你提供一次助戰。\n\n<Title: 等級補償>\n·在貓的「報恩」中有等級補償機制，以便各位守密人能夠並肩作戰！\n等級補償規則如下：\n ·調查隊伍中，等級不足 60 級的喚醒體在本次挑戰中將會補償至 60 級。\n ·調查隊伍中，技能等級不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n ·調查隊伍中，「瘋狂預兆」不足 6 級的喚醒體在本次挑戰中將會補償至 6 級。\n ·調查隊伍中，「靈塑適性」不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n ·若守密人等級不足60級，在本次挑戰中將會補償至60級。\n\n<Title:黑貓抓捕記錄>\n·活動期間，守密人在戰勝對應的「維度黑貓」後，可累積對應任務進度，在「黑貓抓捕記錄」中領取相應獎勵，分為「個人抓捕記錄」與「校園抓捕記錄」。「個人抓捕記錄」為守密人的個人任務。「校園抓捕記錄」為校園全體守密人的任務。\n\n<Title:抓捕排行>\n·活動期間，守密人可以在「抓捕排行」中查看「抓捕次數榜」與「協助次數榜」。\n\n<Title:活動時間>\n· 6 月 15 日 9：00 （GMT+8）前，守密人可進入活動頁參與活動。在此時間後不再接受新的守密人加入挑戰。若活動尚未結束，已參與的守密人可繼續進行挑戰。\n·若在 6 月 15 日 9：00 （GMT+8）前達成「抓捕總數」，則活動將在 6 月 29 日 9：00 （GMT+8）結束。若未在 6 月 15 日 9：00 （GMT+8）前達成「抓捕總數」，則活動在達成「抓捕總數」的 14 天後結束。"
  },
