  Activity_140081_ActivityTips = {
    Text = "<Title:活動規則>\n·「爆燃之主」活動開啟期間，守密人可使用包含凱蒂古拉的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_140082_ActivityName = {
    Text = "墜臨的萬千耀光·復刻"
  },
  Activity_140082_ActivityPlot = {
    Text = "它們高頌永不遺忘的歌，迎接永不熄滅的主。\n祂將攜萬千耀光自極天墜下，訴說永世不滅的輝煌。\n當祂降臨之時，琥珀色的光便覆罩了世界。\n這是祂送給世界的葬禮。"
  },
  Activity_140082_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「隱秘的據點」"
  },
  Activity_140082_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可通過限時玩法「燼滅追獵」、「無紛之宴」和「成就獎勵」收集活動貨幣「財富之」印「」、「死亡之」印「」、「戰爭之」印「」，「財富之」印「」、「死亡之」印「」、「戰爭之」印「」可在「隱密的據點」中購買商品，包括活動限定SR命輪「迫近的太陽」、流明之芯、無垢之芯等。\n2、活動期間，「不朽極晝」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：凱蒂古拉」！\n\n<Title:活動時間>\n1、9 月 7 日 9：00 - 10 月 5 日 9：00（UTC+8），所有活動玩法均可參與。\n2、10 月 5 日 9：00 - 10 月 12 日 9：00（UTC+8），僅可參與「隱密的據點」和成就獎勵。\n\n<Title:燼滅追獵>\n1、「燼滅追獵」包含 7 個關卡，每 1 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 隱密的據點>\n「隱密的據點」共有三個商店，開啟時間如下：\n·「藏品寶庫」： 9 月 7 日 9 時開啟。\n·「委託密室」： 9 月 8 日 9 時開啟。\n·「作戰營帳」： 9 月 9 日 9 時開啟。\n在商店內可以選擇商品直接進行購買。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「燼滅追獵」關卡任務報酬中的「財富之」印「」、「死亡之」印「」、「戰爭之」印「」獲得額外的掉落加成，具體加成如下：\n·喚醒體「凱蒂古拉」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「琥珀色的死亡」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「迫近的太陽」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title: 無紛之宴>\n1、每小時自動獲得 60「財富之」印「」，最多儲存 25 小時。\n\n<Title:意識潛游>\n1、活動期間，「不朽極晝」可免費解鎖。\n2、活動結束後，「不朽極晝」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「不朽極晝」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「意識潛游：不朽極晝」後都可以獲得「鑰令：不落的太陽」。"
  },
