  Activity_140188_ActivityTips = {
    Text = "<Title:簡介>\n·活動期間，守密人在「源液提取」中累計提取指定數量的源液後，可以在「愛意源流」中領取對應獎勵。\n·請注意，「源液提取」中贈送的源液不會計入活動中的源液累計提取數量。"
