  Activity_141466_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_141467_ActivityName = {
    Text = "鏡像囚徒·復刻"
  },
  Activity_141467_ActivityPlot = {
    Text = "飛鳥啊飛鳥，你的腳上為何有斷裂的鐐銬？\n飛鳥啊飛鳥，你為何在高空之上孤獨地鳴叫？\n掙脫荊棘、逃離囚籠，你展翅飛過了漫漫黃沙，只是你悲傷的鳴叫不曾停止。究竟何人，才是你尋找的忠誠旅伴？究竟何處，才是你尋找的真正家鄉？"
  },
  Activity_141467_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「求知的願望」"
  },
  Activity_141467_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可通過限時玩法「飛躍青空」、「夢境巡梭」和「成就獎勵」收集活動貨幣「常識之書」、「數理之書」、「文學之書」，「常識之書」、「數理之書」、「文學之書」可在「求知的願望」中購買商品，包括活動限定SR命輪「孤羽」、流明之芯、無垢之芯等。\n2、活動期間，「異夢視界：天邊之外·上」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：卡斯托爾」！\n\n<Title:活動時間>\n1、10 月 5 日 9：00 - 11 月 2 日 9：00（UTC+8），所有活動玩法均可參與。\n2、11 月 2 日 9：00 - 11 月 9 日 9：00（UTC+8），僅可參與「求知的願望」和成就獎勵。\n\n<Title:飛躍青空>\n1、「飛躍青空」包含 7 個關卡，每 1 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 求知的願望>\n「求知的願望」共有三個商店，開啟時間如下：\n·「通識選修課」： 10 月 5 日 9 時開啟。\n·「科學選修課」： 10 月 6 日 9 時開啟。\n·「文學選修課」： 10 月 7 日 9 時開啟。\n在商店內可以選擇商品直接進行購買。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「飛躍青空」關卡任務報酬中的「常識之書」、「數理之書」、「文學之書」獲得額外的掉落加成，具體加成如下：\n·喚醒體「卡斯托爾」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「無法承受的自由」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「孤羽」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title: 夢境巡梭>\n1、每小時自動獲得 60「常識之書」，最多儲存 25 小時。\n\n<Title:異夢視界>\n1、活動期間，「異夢視界：天邊之外·上」可免費解鎖。\n2、活動結束後，「異夢視界：天邊之外·上」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「異夢視界：天邊之外·上」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「異夢視界：天邊之外·上」後都可以獲得「鑰令：錯位命運」。"
  },
  Activity_141467_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_141509_ActivityName = {
    Text = "秘境遊記"
  },
  Activity_141509_ActivityTips = {
    Text = "<Title:活動規則>\n1、守密人完成指定的紀行任務後，可以在「秘境遊記」中領取獎勵。\n2、「秘境遊記」將會在 7 月 27 日 09：00 結束。\n3、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_141509_BannerText = {
    Text = "特別紀行活動限時開啟！"
  },
  Activity_141533_ActivityName = {
    Text = "永遠的厄波揚斯"
  },
  Activity_141533_ActivityPlot = {
    Text = "讓我們縱聲大笑，讓我們徹夜歡慶。\n讓我們的鉤爪刺穿敵人的咽喉，讓庸常的時光在深淵裡生鏽。\n我們再也不會被衰老、平凡和孤獨抓住。\n這裡是厄波揚斯，我們永遠快樂，我們永遠相聚。\n我們永不分離。"
  },
  Activity_141533_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「無邊獵場」"
  },
  Activity_141533_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可通過限時玩法「高屋巡獵」和「成就獎勵」收集活動貨幣「新鮮的」獵物「」「碩大的」獵物「」「古老的」獵物「」，並在「無邊獵場」中兌換商品，包括活動限定SR命輪「指向歧路的羅盤」、流明之芯、無垢之芯等。\n2、活動期間，「意識潛游：永遠的厄波揚斯」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：龐托斯」！\n\n<Title:活動時間>\n1、6 月 29 日 9：00 - 7 月 27 日 9：00（UTC+8），所有活動玩法均可參與。\n2、7 月 27 日 9：00 - 8 月 3 日 9：00（UTC+8），僅可參與「無邊獵場」和成就獎勵。\n\n<Title:高屋巡獵>\n1、「高屋巡獵」包含 7 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 無邊獵場>\n「無邊獵場」共有三個商店，開啟時間如下：\n·「鐵弓箭」： 6 月 29 日 9 時開啟。\n·「熱武器」： 6 月 30 日 9 時開啟。\n·「魔法」： 7 月 1 日 9 時開啟。\n在商店內可以選擇商品直接進行購買。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「高屋巡獵」關卡任務報酬中三種活動貨幣的掉落獲得額外加成：\n·喚醒體「龐托斯」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「活囚籠」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「指向歧路的羅盤」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title:意識潛游>\n1、活動期間，「意識潛游：永遠的厄波揚斯」可免費解鎖。\n2、活動結束後，調查進度將保留，活動期間未完成的調查事件在活動後繼續完成同樣可獲得對應獎勵。如活動期間未解鎖，活動結束後仍可消耗「現實起點」× 3 解鎖。\n3、無論是否在活動期間，通關「意識潛游：永遠的厄波揚斯」均可獲得「鑰令：空心人」。"
  },
  Activity_141533_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_141534_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_141535_ActivityName = {
