  Activity_145458_ActivityName = {
    Text = "利維坦的遊戲"
  },
  Activity_145458_ActivityPlot = {
    Text = "貪婪的英雄想要不朽的王座，絕望的母親想要復生的子，瘋狂的術士想要禁忌的知識—— 他們跪在祂的面前，用祂聽了萬年的措辭乞求。\n祂賜予他們一切，然後看他們失去一切。祂看過四千場慘烈的角逐，卻從不饜足。\n這一次，鬥獸場的大門為你敞開。來吧，告訴祂，你渴望著什麼。\n告訴祂，你與那四千個亡魂，究竟有何不同。"
  },
