  },
  Activity_145458_ActivityTips = {
    Text = "<Title:活動簡介>\n活動期間，守密人可通過限時玩法「貪戮角逐」和「成就獎勵」收集活動貨幣「血色祭品」，「血色祭品」可在「鬥獸場祭祀台」中換取獎勵，包括活動限定SR命輪「不滅的飢骨」、流明之芯、無垢之芯、賢石碎屑、擬態凝晶等。\n\n<Title:貪戮角逐>\n1、「貪戮角逐」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣「血色祭品」。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「貪戮角逐」關卡任務報酬中的「血色祭品」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「蝕滅·蘿坦」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「天之隕」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「不滅的飢骨」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title:意識潛游>\n1、活動期間，「意識潛游：直至鯨天隕落」可免費解鎖。\n2、活動結束後，「意識潛游：直至鯨天隕落」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「意識潛游：直至鯨天隕落」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「意識潛游：直至鯨天隕落」後都可以獲得「鑰令：噬鯨的風暴」。\n\n<Title:活動時間>\n1、7 月 27 日 9:00 - 8 月 24 日 9:00（UTC+8），活動簡介中的所有內容均可參與。\n2、8 月 24 日 9:00 - 8 月 31 日 9:00（UTC+8），僅保留「鬥獸場祭祀台」和「成就獎勵」，其他內容均已結束不可參與。\n3、8 月 31 日 9:00（UTC+8）後，剩餘未兌換的「血色祭品」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
  Activity_145458_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_145459_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_145465_ActivityName = {
    Text = "如果一切如常·復刻"
  },
  Activity_145465_ActivityPlot = {
    Text = "你曾幻想過，如果災難不曾來臨，所有人的生活究竟會是什麼樣子。\n你拯救世界的力量沒有了用武之地， 每天都要為平凡的校園生活和賺取可憐的學分奔波。操場上再也沒有了訓練作戰的身影，取而代之的是一排排社團活動的帆布棚子，與招攬、嬉鬧的叫嚷聲；待放學的鐘聲敲響，飢餓的學生們便立刻擠滿了食堂……\n敲開你牽掛著的人們的房門，你會看到怎樣的笑臉？"
  },
  Activity_145465_ActivityStageEndContent = {
    Text = "【如果一切如常】活動已結束，當前僅可參與「學生會辦公樓」"
  },
  Activity_145465_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可通過限時玩法「陽光下新事」收集活動貨幣「海濱特產貝殼」，「海濱特產貝殼」可在「學生會辦公樓」中購買商品，包括流明之芯、無垢之芯、賢石碎屑等。\n2、活動期間，「異夢視界：派遣紀錄」限時免費解鎖！\n\n<Title:活動時間>\n1、8 月 3 日 9:00 - 8 月 17 日 9:00（UTC+8），所有活動玩法均可參與。\n2、8 月 17 日 9:00 - 8 月 24 日 9:00（UTC+8），僅可參與「學生會辦公樓」和成就獎勵。\n\n<Title:陽光下新事>\n1、「陽光下新事」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 學生會辦公樓>\n「學生會辦公樓」共有一個商店， 8 月 3 日 9 時開啟。\n在商店內可以選擇商品直接進行購買。\n\n<Title:異夢視界>\n1、活動期間，「異夢視界：派遣紀錄」可免費解鎖。\n2、活動結束後，「異夢視界：派遣紀錄」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「異夢視界：派遣紀錄」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「異夢視界：派遣紀錄」後都可以獲得「鑰令：美夢一剎」。"
  },
  Activity_145465_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_145466_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_145717_ActivityName = {
    Text = "新月與深雪"
  },
  Activity_145717_ActivityPlot = {
    Text = "七重禮拜，三重宣誓，只要懷著對那純白仙女虔誠的信仰攀上天與雪的交際，她就會實現你所有、所有的願望。\n每一個人都有不同的目的，每一個目的下都有不同的謊言。\n將祂們挖掘，將祂們呈現——在屈從於無瑕的表象之前。\n不要和她一同沒入這片深雪。"
  },
  Activity_145717_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「仙女典儀」"
  },
  Activity_145717_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可通過限時玩法「烏摩鉢蒂的寶物」和「成就獎勵」收集活動貨幣「紅蘋果」「金蘋果」「糖蘋果」，並在「仙女典儀」中兌換商品，包括活動限定SR命輪「甜美真相」、流明之芯、無垢之芯等。\n2、活動期間完成活動成就還能獲得活動限定頭像「以銀鑰之名：卡拉布」！\n\n<Title:活動時間>\n1、8 月 24 日 9:00 - 9 月 21 日 9:00（UTC+8），所有活動玩法均可參與。\n2、9 月 21 日 9:00 - 9 月 28 日 9:00（UTC+8），僅可參與「仙女典儀」和成就獎勵。\n\n<Title:烏摩鉢蒂的寶物>\n1、「烏摩鉢蒂的寶物」包含 7 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 仙女典儀>\n1、「仙女典儀」共有三個商店，開啟時間如下：\n·「淺雪賜福」： 8 月 24 日 9 時開啟。\n·「寒霜賜福」： 8 月 25 日 9 時開啟。\n·「純白賜福」： 8 月 26 日 9 時開啟。\n2、每次「沐受賜福」將消耗「紅蘋果」/「金蘋果」/「糖蘋果」× 750，隨機獲得「仙女典儀」中的五個物品獎勵。\n3、每個「仙女典儀」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「烏摩鉢蒂的寶物」關卡任務報酬中三種活動貨幣的掉落獲得額外加成：\n·喚醒體「卡拉布」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「蜜果的謊言」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「甜美真相」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、多項「活動加成」可疊加計算。 \n3、注意，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。"
  },
