  Activity_148889_ActivityTips = {
    Text = "<Title:活動規則>\n·「本源奧吉爾」活動開啟期間，守密人可使用包含本源奧吉爾的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
