  Activity_15793_ActivityPlot = {
    Text = "每個下著雨的夜晚，都伴隨著失意與寂寥。\n有人失去愛情，有人失去尊嚴。\n還有人失去自己的頭顱。"
  },
  Activity_15793_ActivityTips = {
    Text = "<Title:參與條件>\n·完成「調查行動」2-9·普通後可參與。\n<Title:調查事件>\n·活動期間，每天會推出「雨鎮幽影」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「雨鎮幽影」的調查進度會保留，守密人可以在特遣紀錄中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「雨鎮幽影」普通模式和完成「雨鎮幽影」的調查事件後，可以獲得無垢之芯、賢者之石和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
