    Text = "活動規則：\n1、「強效特訓」活動期間，守密人通關「史瓦西喉」後，部分素材獎勵將會翻倍，每天可享受3次。\n2、當日未使用完畢的雙倍獎勵次數將在次日9點（GMT+8）清空，請守密人記得及時使用喔~"
  },
