  },
  Activity_20690_ActivityName = {
    Text = "升格演繹"
  },
  Activity_20690_ActivityTips = {
    Text = "活動規則：\n1、「升格演繹」活動期間，守密人通關「渾濁殘像」後，部分素材獎勵將會翻倍，每天可享受3次。\n2、當日未使用完畢的雙倍獎勵次數將在次日9點（GMT+8）清空，請守密人記得及時使用喔~"
  },
  Activity_20691_ActivityName = {
    Text = "獵顱魔女"
  },
  Activity_20691_ActivityTips = {
    Text = "<Title:活動規則>\n·「獵顱魔女」活動開啟期間，守密人可使用包含達芙黛爾的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_21502_ActivityTips = {
    Text = "<Title:活動規則>\n·「海之使徒」活動開啟期間，守密人可使用包含彌利亞姆的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_21781_ActivityName = {
    Text = "研習自選"
  },
  Activity_21781_ActivityPlot = {
    Text = "完成任務，可任選「界域研習」中的特定喚醒體或「輪轉之相」中的特定命輪！"
  },
  Activity_21781_ActivityTips = {
    Text = "活動規則：\n1、累計喚醒 50 次、累計登入3天、累計登入 7 天，可獲得「原質樂園」獎勵。「原質樂園」可在「物資：消耗品」中使用，使用後可任選1名「界域研習」中的特定喚醒體喚醒。\n2、累計喚醒 300 次、累計喚醒 1000 次、累計登入 30 天，可獲得「輪轉之書」獎勵。「輪轉之書」可在「物資：消耗品」中使用，使用後可任選1個「輪轉之相」中的特定命輪獲得。"
  },
  Activity_22367_ActivityName = {
    Text = "靈知迸發"
  },
  Activity_22367_ActivityTips = {
    Text = "活動規則：\n1、「靈知迸發」活動期間，守密人在「製劑淬煉」調查或重現，將獲得額外50%的獎勵（守密人經驗除外），每天不限次。"
  },
  Activity_23671_ActivityName = {
    Text = "深潛對弈"
  },
  Activity_23671_ActivityPlot = {
    Text = "活動期間，守密人透過「幻夢深潛」和「相位對弈」獲取的守密人經驗將會翻倍，每日上限提升至480點。"
  },
  Activity_23671_ActivityTips = {
    Text = "活動規則：\n1、「深潛對弈」活動期間，守密人透過「幻夢深潛」和「相位對弈」獲取的守密人經驗將會翻倍，每日上限提升至480點。若同時解鎖了核心課題，透過該途徑獲得的守密人經驗將會翻倍再翻倍，每日上限維持480點不變。\n2、當日未使用完畢的雙倍守密人經驗將在次日9點（GMT+8）清空，守密人記得及時清空哦~"
  },
  Activity_23693_ActivityName = {
    Text = "蒼白後裔"
  },
  Activity_23693_ActivityPlot = {
    Text = "相傳在倫蒂尼恩的地下，有一扇唯一的門。\n它通向蒼白之主的所在……"
  },
  Activity_23693_ActivityTips = {
    Text = "<Title:參與條件>\n·完成意識潛游「騎士的願望」普通模式後可參與。 \n<Title:調查事件>\n·活動期間，每天會推出「蒼白後裔」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「蒼白後裔」的調查進度會保留，守密人可以在意識潛游中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「蒼白後裔」普通模式和完成「蒼白後裔」的調查事件後，可以獲得漆黑鎖扣和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
  Activity_23693_UnlockConditionExplanation = {
    Text = "完成意識潛游「騎士的願望」後解鎖"
  },
  Activity_23723_ActivityName = {
    Text = "風暴將至"
  },
  Activity_23723_ActivityTips = {
    Text = "活動規則：\n1、活動期間，調查行動第五章臨時關閉，鑰令「永世執念」暫時由通關調查行動第四章獲得。\n2、活動結束後，調查行動第五章再度開放，鑰令「永世執念」仍然需要通關調查行動第五章。\n3、另外，此前已達成的第五章成就獎勵、關卡成就獎勵、探索獎勵、通關獎勵都會保留，再度開放時（當前計劃為  12 月 27 日），相關已完成進度會盡可能平移保留，無需重複完成。"
  },
  Activity_23870_ActivityTips = {
    Text = "活動規則：\n1、活動期間，完成活動任務即可獲得獎勵。\n2、活動結束後，未領取的活動獎勵將無法再領取，請守密人記得及時領取~"
  },
