  Activity_24036_ActivityTips = {
    Text = "活動規則：\n1、「深潛對弈」活動期間，守密人透過「幻夢深潛」和「相位對弈」獲取的守密人經驗將會翻倍，每日上限提升至480點。若同時解鎖了核心課題，透過該途徑獲得的守密人經驗將會翻倍再翻倍，每日上限維持480點不變。\n2、當日未使用完畢的雙倍守密人經驗將在次日9點（GMT+8）清空，守密人記得及時清空哦~"
