  },
  Activity_24194_ActivityName = {Text = "紅夫人"},
  Activity_24194_ActivityTips = {
    Text = "<Title:活動規則>\n·「紅夫人」活動開啟期間，守密人可使用包含索蕾爾的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_24195_ActivityTips = {
    Text = "<Title:活動規則>\n·「淤泥之花」活動開啟期間，守密人可使用包含莉莉的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_24992_ActivityName = {
    Text = "學園禮贈"
  },
  Activity_24992_ActivityTips = {
    Text = "活動規則：\n1、守密人每天登入後可以在「學園禮贈」中領取當日簽到獎勵。\n2、獎勵將根據守密人累計登入依次解鎖，當日簽到獎勵將在9點（GMT+8）刷新。"
  },
  Activity_25011_ActivityName = {
    Text = "一步之遙"
  },
  Activity_25011_ActivityPlot = {
    Text = "你向前一步，跨入了另一個時空。"
  },
  Activity_25011_ActivityTips = {
    Text = "<Title:參與條件>\n·完成意識潛游「騎士的願望」普通模式後可參與。 \n<Title:調查事件>\n·活動期間，每天會推出「一步之遙」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「一步之遙」的調查進度會保留，守密人可以在意識潛游中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「一步之遙」普通模式和完成「一步之遙」的調查事件後，可以獲得幸運糖果和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
  Activity_25011_UnlockConditionExplanation = {
    Text = "完成意識潛游「騎士的願望」後解鎖"
  },
  Activity_25012_ActivityName = {
    Text = "薔薇禮讚"
  },
  Activity_25012_ActivityPlot = {
    Text = "女士們，先生們。\n溫和的良夜已經拉開帷幕，準備好手邊的佳釀吧。\n這是一個漫長的故事，且聽我們慢慢道來……"
  },
  Activity_25012_ActivityTips = {
    Text = "<Title:參與條件>\n·完成「調查行動」2-9·普通後可參與。\n<Title:調查事件>\n·活動期間，每天會推出「薔薇禮讚」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「薔薇禮讚」的調查進度會保留，守密人可以在特遣紀錄中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「薔薇禮讚」普通模式和完成「薔薇禮讚」的調查事件後，可以獲得無垢之芯、賢者之石和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
  Activity_25012_UnlockConditionExplanation = {
    Text = "完成 「調查行動」2-9·普通 後解鎖"
  },
  Activity_34754_ActivityTips = {
    Text = "<Title:參與條件>\n·完成「調查行動」2-9·普通後可參與。\n<Title:調查事件>\n·活動期間，每天會推出「故事的魔法」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「故事的魔法」的調查進度會保留，守密人可以在特遣紀錄中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「故事的魔法」普通模式和完成「故事的魔法」的調查事件後，可以獲得無垢之芯、賢者之石和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
  Activity_34755_ActivityTips = {
    Text = "<Title:活動簡介>\n·活動期間「劇本迷思」玩法限時開啟，且「特遣紀錄：故事的魔法」免費解鎖開啟！\n\n<Title:劇本迷思>\n·「劇本迷思」共包含 9 個難度的關卡，推薦等級範圍為 30~70，通關較低的難度的關卡後解鎖更高難度的關卡。\n·每次挑戰需要消耗靈啡肽×60，每次通關後都可以獲得活動貨幣「飄零的靈感」。關卡難度越高，獲取的「飄零的靈感」就越多！\n·「飄零的靈感」可以在「魔法劇本商店」兌換大量的喚醒體培養素材，還可以兌換活動限定 SR 命輪「35mm的魔法」，該命輪在未來可能會再次推出或加入常駐喚醒。\n·每次挑戰時，除首領之外的敵人、事件、地圖都可能發生一定的變化，關卡內可能出現的造物也更多！\n·在「劇本迷思」中可以使用校友會助戰。\n\n<Title:共鳴與成就>\n·消耗「演繹之心」，啟動「共鳴：導演密碼」，可以讓守密人在「劇本迷思」中變得更強，挑戰更加輕鬆。\n·守密人可以透過達成活動成就獲取「演繹之心」，除此之外透過活動成就還可以獲得活動限定頭像「以銀鑰之名：莉莉」！\n\n<Title:特遣紀錄>\n·活動期間，每天會推出「故事的魔法」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「故事的魔法」的調查進度會保留，守密人可以在特遣紀錄中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。\n·活動期間會推出限時成就獎勵，守密人通關「故事的魔法」普通模式和完成「故事的魔法」的調查事件後，可以在活動成就中領取銀芯獎勵！成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n"
  },
