  Activity_35844_ActivityTips = {
    Text = "<Title:活動規則>\n·「深海淑女」活動開啟期間，守密人可使用包含墨菲的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_35983_ActivityName = {
    Text = "學園禮贈"
  },
  Activity_35983_ActivityTips = {
    Text = "活動規則：\n1、守密人每天登入後可以在「學園禮贈」中領取當日簽到獎勵。\n2、獎勵將根據守密人累計登入依次解鎖，當日簽到獎勵將在9點（GMT+8）刷新。"
  },
  Activity_36841_ActivityName = {
    Text = "諸事如常"
  },
  Activity_36841_ActivityPlot = {
    Text = "這是奧瑞塔簡單而開心的一天，這是她的每一天。"
  },
  Activity_36841_ActivityTips = {
    Text = "<Title:參與條件>\n·完成意識潛游「騎士的願望」普通模式後可參與。 \n<Title:調查事件>\n·活動期間，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「諸事如常」的調查進度會保留，守密人可以在意識潛游中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「諸事如常」普通模式和完成「諸事如常」的調查事件後，可以獲得漆黑鎖扣和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
  Activity_36841_UnlockConditionExplanation = {
    Text = "完成意識潛游「騎士的願望」後解鎖"
  },
  Activity_36885_ActivityName = {
    Text = "燃燒的群宴"
  },
  Activity_36886_ActivityName = {
    Text = "荊棘女王"
  },
  Activity_36886_ActivityTips = {
    Text = "<Title:活動規則>\n·「荊棘女王」活動開啟期間，守密人可使用包含旺達的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_38716_ActivityName = {
    Text = "調查重啟"
  },
  Activity_38716_ActivityTips = {
    Text = "<Title:活動簡介>\n·守密人可以在「返校獎勵」中直接領取「重啟補給」獎勵。\n·完成指定的訓練任務，可以在「調查重啟」活動中領取獎勵。\n·完成全部訓練任務，還可領取額外獎勵。"
  },
  Activity_38717_ActivityName = {
    Text = "返校報到"
  },
  Activity_38717_ActivityTips = {
    Text = "<Title:活動簡介>\n·守密人每天登入後可以在「返校報到」中領取當日簽到獎勵。\n·獎勵將根據守密人累計登入依次解鎖，當日簽到獎勵將在9點（GMT+8）刷新。"
  },
  Activity_38805_ActivityName = {
    Text = "燃燒的群宴"
  },
  Activity_38805_ActivityPlot = {
    Text = "伊薩拉烏，湖中之城，據說是旺達故鄉的所在。\n這次你將穿過夢境的大門，抵達那遍布鐘舌的古老塔群……"
  },
  Activity_38805_ActivityTips = {
    Text = "<Title:活動簡介>\n·活動期間「燃燒的群宴」玩法限時開啟，且「意識潛遊：燃燒的群宴」限時免費解鎖！\n\n<Title:湖中之城>\n·「湖中之城」有 7 個關卡，每 2 天開放 1 個！每個關卡的敵人與事件都可能發生隨機變化。\n·請注意，每個關卡獎勵的素材種類、數量、混合比例都可能發生變化，越早開放的關卡種類更單純，越晚開放的關卡種類更豐富但總量會更多，請按自己的需要選擇攻略方法吧！\n·每個關卡共包含 7 個難度的關卡，推薦等級範圍為 15~65，所有難度均預設解鎖。\n·每次挑戰需要消耗靈啡肽×120，難度越高，獲取的獎勵就越多，請選擇適合自己的難度進行挑戰。\n·關卡獎勵的素材可以在「旺達的奇珍寶匣」商店兌換大量的喚醒體培養素材，還有活動限定頭像「以銀鑰之名：旺達」。\n·可以使用校友會助戰和「共鳴：代行密令」來幫助你更輕鬆地過關。。\n\n<Title:共鳴與成就>\n·消耗「享樂之心」，啟動「共鳴：代行密令」，可以讓守密人在「湖中之城」中變得更強，挑戰更加輕鬆；也可以讓守密人在通關時獲得額外的活動貨幣。\n·守密人可以透過達成活動成就獲取「享樂之心」，也可在「旺達的奇珍寶匣」商店兌換。\n\n<Title:意識潛遊>\n·活動期間，「燃燒的群宴」可免費解鎖。每天會推出「燃燒的群宴」中一個新的調查事件，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「燃燒的群宴」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「燃燒的群宴」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n·活動期間會推出限時成就獎勵，守密人完成「燃燒的群宴」的調查事件後，可以在活動成就中領取銀芯獎勵！成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n"
  },
  Activity_41378_ActivityName = {
    Text = "迎災特訓"
  },
  Activity_41378_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的任務後，可以在「迎災特訓」中領取獎勵。\n2、「迎災特訓」永久開放。\n3、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_43569_ActivityName = {
    Text = "遠洋紀行"
  },
  Activity_43569_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「遠洋紀行」中領取獎勵。\n2、「遠洋紀行」永久開放。\n3、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_43570_ActivityName = {
    Text = "雪鎮紀行"
  },
  Activity_43570_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「雪鎮紀行」中領取獎勵。\n2、「雪鎮紀行」永久開放。\n3、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_43572_ActivityName = {
    Text = "煉金美學"
  },
  Activity_43572_ActivityTips = {
    Text = "活動規則：\n1、「煉金美學」活動期間，守密人在「金券搜查」調查或重現，將獲得額外100%的獎勵（守密人經驗除外），每天限 6 次。"
  },
  Activity_43573_ActivityName = {
    Text = "煉金美學"
  },
  Activity_43573_ActivityTips = {
    Text = "活動規則：\n1、「煉金美學」活動期間，守密人在「金券搜查」調查或重現，將獲得額外50%的薔薇金券獎勵。"
  },
  Activity_43574_ActivityName = {
    Text = "煉金美學"
  },
  Activity_43574_ActivityTips = {
    Text = "活動規則：\n1、「煉金美學」活動期間，守密人在「金券搜查」調查或重現，將獲得額外50%的薔薇金券獎勵。"
  },
  Activity_44273_ActivityName = {
    Text = "靈魂的牧人"
  },
  Activity_44273_ActivityPlot = {
    Text = "他為你們受過苦，擔了你們的劫難。\n因他付出的血肉，你們得了醫治；\n因他付出的生命，你們得了寬恕。"
  },
  Activity_44273_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「聖堂之路」、「市民的善意」和「成就獎勵」收集活動貨幣「義賣券」，「義賣券」可在「聖堂義賣現場」中換取隨機商品，包括活動限定SR命輪「鏡中人」、無垢之芯、流明之芯等。\n2、通關「特遣紀錄：血的顏色」可獲得全新鑰令「神蹟降臨」。活動期間，「特遣紀錄：血的顏色」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：薩爾瓦多」！\n\n<Title:聖堂之路>\n1、「聖堂之路」包含 5 個關卡，守密人透過完成「特遣紀錄：血的顏色」的第2/4/6/7/9關可逐個解鎖。\n2、每個關卡都有 7 個難度，推薦等級為 15~65，所有難度均預設解鎖。每個關卡的敵人與事件都可能發生隨機變化。\n3、可以使用校友會助戰和「共鳴：靈魂的岔路」來幫助你更輕鬆地過關。\n4、每次挑戰需要消耗 120 靈啡肽，難度越高，通關獲取的「義賣券」就越多，此外守密人可以選擇雙倍挑戰，消耗 240 靈啡肽，獲得雙倍的「義賣券」和守密人經驗。\n\n<Title:輝光加成>\n1、在「靈魂輝光」的影響下，喚醒體「薩爾瓦多」、SSR命輪「神言石板」和SR命輪「鏡中人」可以使「聖堂之路」關卡任務報酬中的「義賣券」獲得額外的掉落加成，具體加成如下：\n（1）方式一：守密人擁有特定喚醒體或命輪（不要求上陣）\n·喚醒體「薩爾瓦多」：啟靈0/1/2/3及以上，加成30%/40%/50%/60%。\n·SSR命輪「神言石板」：疊位0/1/2/3及以上，加成30%/40%/50%/60%。\n·SR命輪「鏡中人」：疊位0/1/2/3及以上，加成15%/20%/25%/30%。\n（2）方式二：使用特定喚醒體或命輪助戰\n·喚醒體「薩爾瓦多」：加成10% 。\n·SSR命輪「神言石板」：加成10% 。\n·SR命輪「鏡中人」：加成5% 。\n2、對於同一喚醒體或命輪，兩種方式的「輝光加成」取其中加成更高的方式生效，不疊加。\n3、不同喚醒體或命輪的「輝光加成」以疊加的方式結算，按照上述的規則，守密人最多可以獲得 150% 的「輝光加成」！\n\n<Title:共鳴：靈魂的岔路>\n1、守密人可以透過完成活動成就獲取「懺悔之心」。 \n2、消耗「懺悔之心」，啟動「共鳴：靈魂的岔路」，可以獲得以下加成：\n（1）讓守密人在活動玩法「聖堂之路」和「特遣紀錄：血的顏色」中變得更強，挑戰更加輕鬆。\n（2）提升完成「聖堂之路」挑戰後獲得的同調率。\n（3）啟動活動玩法「市民的善意」。\n\n<Title:市民的善意>\n1、啟動共鳴「輕鬆的方式」後，每小時自動獲得60「義賣券」，最多儲存 25 小時。\n2、啟動共鳴「贖罪，贖罪」後，每小時額外自動獲得 1800 薔薇金券。\n\n<Title: 聖堂義賣現場>\n1、守密人可以使用「義賣券」在「聖堂義賣現場」的商鋪中隨機換取商品，活動限定SR命輪「鏡中人」、流明之芯和無垢之芯等商品在等著你~\n2、聖堂義賣現場共有三個商鋪，開啟時間如下：\n·商鋪「格雷太太的小店」：初始開啟。\n·商鋪「大約翰的神奇義賣」：活動第4天開啟。\n·商鋪「史密斯特賣」：活動第7天開啟。\n3、不同商鋪的商品有所不同，守密人可根據自己的需要選擇商品進行換取。\n4、每個商鋪中都包含特殊商品和普通商品，每次換取將消耗600「義賣券」，隨機獲得商鋪中的五個商品。\n5、當商鋪中的所有特殊商品被換取後，守密人可以要求商鋪補充貨物，也可以選擇繼續換取。當商鋪中所有的商品都被換取後，守密人需選擇補充貨物後才可繼續換取。\n6、每個商鋪的前2次補充貨物，商鋪中所有商品的剩餘數量會補充至上限，從第3次補充貨物開始，特殊商品將不再補充，只補充普通商品。補充貨物後，此前未換取完畢商品的剩餘數量不會保留，請守密人仔細思考後再選擇補充貨物噢~\n\n<Title:特遣紀錄>\n1、活動期間，特遣紀錄「血的顏色」可免費解鎖。每隔2天會推出「血的顏色」新的調查事件，完成調查事件後可以獲得鑰令「神蹟降臨」、無垢之芯、調查徽章和守密人經驗等調查獎勵。\n2、活動結束後，「血的顏色」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「血的顏色」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、活動期間會推出限時成就獎勵，守密人完成「血的顏色」的所有調查事件後，可以在活動成就中領取頭像「以銀鑰之名：薩爾瓦多」！成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n\n"
  },
