  Activity_44705_ActivityTips = {
    Text = "活動規則：\n1、守密人每天登入後可以在「學園禮贈」中領取當日簽到獎勵。\n2、獎勵將根據守密人累計登入依次解鎖，當日簽到獎勵將在9點（GMT+8）刷新。"
