  Activity_45664_ActivityName = {
    Text = "巨人的隕落"
  },
  Activity_45664_ActivityPlot = {
    Text = "無盡的海洋、烈日，被流放的非利士英雄和他唯一的隨從。\n這是一個關於「尋找」的故事。"
  },
  Activity_45664_ActivityTips = {
    Text = "<Title:參與條件>\n·完成意識潛游「騎士的願望」普通模式後可參與。 \n<Title:調查事件>\n·活動期間，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「巨人的隕落」的解鎖狀態和調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵；若活動期間未解鎖，則活動結束後可消耗 現實起點×3 解鎖。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「巨人的隕落」普通模式和完成「巨人的隕落」的調查事件後，可以獲得維度凝晶和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
  Activity_45664_UnlockConditionExplanation = {
    Text = "完成意識潛游「騎士的願望」後解鎖"
  },
  Activity_46167_ActivityTips = {
    Text = "<Title:活動規則>\n·「分裂患者·混沌」活動開啟期間，守密人可使用包含「24」的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
