  Activity_46609_ActivityName = {
    Text = "多重療癒"
  },
  Activity_46609_ActivityPlot = {
    Text = "Hysteria，又名歇斯底里症、癔症。\n在你們身處的年代，它與死亡同義。\n\n幸運的是，彌薩格的科學家和調查員同樣瘋狂：他們決心攻克這一難題。"
  },
  Activity_46609_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「人格解析」"
  },
  Activity_46609_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「記憶編碼」、「邊緣存儲」和「成就獎勵」收集活動貨幣「記憶拼圖」，「記憶拼圖」可在「人格解析」中購買商品，包括活動限定SR命輪「銀鱈魚的決心」、流明之芯、無垢之芯、賢者之石和豐厚的培養素材。\n2、通關「特遣紀錄：寧靜的裂殖」可獲得全新鑰令「全部的她」。活動期間，「特遣紀錄：寧靜的裂殖」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：」24「」！\n\n<Title:活動時間>\n1、4 月 27 日 9：00 - 5 月 18 日 9：00（GMT+8），所有活動玩法均可參與，「特遣紀錄：寧靜的裂殖」限時免費解鎖。\n2、5 月 18 日 9：00 - 5 月 25 日 9：00（GMT+8），僅可參與「人格解析」和成就獎勵，「特遣紀錄：寧靜的裂殖」需要消耗現實起點×7解鎖。\n\n<Title:記憶編碼>\n1、「記憶編碼」包含 5 個關卡，守密人透過完成「特遣紀錄：寧靜的裂殖」的第2/4/6/8/10關可逐個解鎖。\n2、每個關卡都有 7 個難度，推薦等級為 15~65，所有難度均預設解鎖。每個關卡的敵人與事件都可能發生隨機變化。\n3、可以使用校友會助戰和「共鳴：分離性症候」來幫助你更輕鬆地過關。\n4、每次挑戰需要消耗 120 靈啡肽，難度越高，通關獲取的「記憶拼圖」就越多，此外守密人可以選擇雙倍挑戰，消耗 240 靈啡肽，獲得雙倍的「記憶拼圖」和守密人經驗。\n\n<Title:理性加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「記憶編碼」關卡任務報酬中的「記憶拼圖」獲得額外的掉落加成，具體加成如下：\n·喚醒體「24」：啟靈0/1/2/3及以上，加成15%/20%/25%/30%。\n·喚醒體「達芙黛爾」：啟靈0/1/2/3及以上，加成15%/20%/25%/30%。\n·SSR命輪「畸體回噬」：疊位0/1/2/3及以上，加成15%/20%/25%/30%。\n·SSR命輪「至為珍貴的藏品」：疊位0/1/2/3及以上，加成15%/20%/25%/30%。\n·SR命輪「銀鱈魚的決心」：疊位0/1/2/3及以上，加成15%/20%/25%/30%。\n2、不同喚醒體或命輪的「理性加成」以疊加的方式結算。 \n\n<Title:共鳴：分離性症候>\n1、守密人可以透過完成活動成就獲取「分裂之心」。 \n2、消耗「分裂之心」，啟動「共鳴：分離性症候」，可以獲得以下加成：\n（1）讓守密人在活動玩法「記憶編碼」和「特遣紀錄：寧靜的裂殖」中變得更強，挑戰更加輕鬆。\n（2）提升完成「記憶編碼」挑戰後獲得的獎勵。\n（3）啟動活動玩法「邊緣存儲」。\n\n<Title: 邊緣存儲>\n·啟動共鳴「診斷：人格分裂」後，每小時自動獲得 60「記憶拼圖α」，最多儲存 25 小時。\n\n<Title:特遣紀錄>\n1、活動期間，「特遣紀錄：寧靜的裂殖」可免費解鎖。每隔2天會推出「寧靜的裂殖」新的調查事件，完成調查事件後可以獲得鑰令「全部的她」、無垢之芯、調查徽章和守密人經驗等調查獎勵。\n2、活動結束後，「特遣紀錄：寧靜的裂殖」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「特遣紀錄：寧靜的裂殖」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、活動期間會推出限時成就獎勵，守密人完成「特遣紀錄：寧靜的裂殖」的所有調查事件後，可以在活動成就中領取頭像「以銀鑰之名：」24「」！成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n\n\n"
  },
