  },
  Activity_48719_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「紊亂情慾」和「成就獎勵」收集活動貨幣「豐穰種核」，「豐穰種核」可在「慾孽滋生」中換取獎勵，包括流明之芯、無垢之芯和豐厚的培養素材。\n2、活動期間，守密人只要完成「調查行動」2-9·普通也可以參與「繁衍狂熱」，且無需滿足喚醒體同調率要求即可解鎖「繁衍狂熱事件」，此外，消耗的「現實起點」數量要求也變為僅需 1 個！\n3、一股神秘力量的到來似乎有助於你與喚醒體建立更深層次的關係，活動期間透過所有方式獲取的同調率翻倍！\n\n<Title:活動時間>\n1、5 月 18 日 9：00 - 6 月 3 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、6 月 3 日 9：00 - 6 月 10 日 9：00（GMT+8），僅保留「慾孽滋生」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title:紊亂情慾>\n1、「紊亂情慾」包含 10 個無需探索直接戰鬥的素材關卡，每天開放 1 個。\n2、在這些素材關卡中，你將直接覺醒所有喚醒體，並獲得預設的造物，此外在 6 回合之後受到 1 次泰旖絲的幫助。\n3、每次挑戰將消耗 60 點靈啡肽，本次活動素材關卡通關後即可支持重現。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title:強慾加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「紊亂情慾」關卡任務報酬中的「豐穰種核」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「泰旖絲」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「慈悲的哺育」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「灼熱的吻別」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「強慾加成」以疊加的方式結算。\n\n<Title:繁衍狂熱>\n1、通關「調查行動」7-3·普通之後，全新特別調查內容「繁衍狂熱」開放！\n2、隨著「慾海翻波」活動的到來，讓喚醒體們受到了神秘力量影響，陷入了「繁衍狂熱」狀態……請各位守密人小心！\n3、當喚醒體的同調率達到 10 級後可以解鎖該喚醒體的「繁衍狂熱事件」，消耗 「現實起點」×7 進行解鎖，完成後可以獲取「無垢之芯」×1！\n4、在「慾海翻波」活動期間（6 月 3 日 9：00前）參與條件放寬至通關「調查行動」2-9·普通，並且喚醒體無需同調率要求即可解鎖「繁衍狂熱事件」，此外消耗的「現實起點」數量要求也變為僅需 1 個！ \n\n<Title: 同調率翻倍>\n1、一股神秘力量的到來似乎有助於你與喚醒體建立更深層次的關係，活動期間透過所有方式獲取的同調率翻倍！\n2、與其他同調率加成的獎勵按照相乘的方式結算，如使用助戰同調率加成。\n<Title:成就獎勵>\n1、完成所有任務可以獲得獎勵：銀芯×800，大量「豐穰種核」，活動限定 SR 命輪「灼熱的吻別」×16，活動限定頭像「以銀鑰之名：泰旖絲」。\n2、包含 16 個任務：通關「紊亂情慾」的每個關卡 1 次，「紊亂情慾」中累計重現 10/20/30/40/50 次，完成所有活動成就。\n\n\n\n"
  },
  Activity_48719_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_48825_ActivityName = {
    Text = "校貓的謝禮"
  },
  Activity_48825_ActivityPlot = {
    Text = "守密人可以從以下限定喚醒體中選擇1名喚醒！"
  },
  Activity_48825_ActivityTips = {
    Text = "<Title:簡介>\n若非諸位的熱切守望，彌薩格或許將永遠埋沒於漫長的黑夜。如今，我們已經踐行了約定，一路走過坎坷，迎來了半週年紀念時刻。為此，校貓將為你獻上一份特殊的禮物，感謝各位一直以來的陪伴。\n\n<Title:活動規則>\n·活動期間，每位守密人可以從8名限定SSR喚醒體中選擇 1 名喚醒，包括圖魯、達芙黛爾、索蕾爾、莉莉、墨菲、旺達、薩爾瓦多、「24」。\n·當守密人選擇已喚醒的喚醒體時，將會轉換為對應喚醒體的殘片×1和根源沉澱×50；若對應喚醒體的啟靈等級已滿，將轉換為「靈核碎片」× 1和「根源沉澱」× 150。"
  },
  Activity_48825_BannerText = {
    Text = "限定喚醒體免費領取"
  },
  Activity_48826_ActivityName = {
    Text = "極夜與破曉"
  },
  Activity_48826_ActivityPlot = {
    Text = "每日登入可領取紀念限定SSR命輪「極夜與破曉」，總計可領取16個！"
  },
  Activity_48826_ActivityTips = {
    Text = "<Title:簡介>\n這是一首獻給玩家的詩歌，關於理想，關於信念，關於攜手共進的時光。願真誠的心永不停止跳動，願銀鑰指引前行。\n\n<Title:活動規則>\n·活動期間，守密人每天登入後可以在「極夜與破曉」中領取紀念限定 SSR 命輪「極夜與破曉」，總計可領取 16 次。\n·獎勵將根據守密人累計登入依次解鎖，當日登入獎勵將在9點（GMT+8）刷新。"
  },
  Activity_48826_BannerText = {
    Text = "限定SSR命輪免費領取"
  },
  Activity_48827_ActivityName = {
    Text = "帽中的銀芯"
  },
  Activity_48827_ActivityPlot = {
    Text = "據不完全統計，在這半年以來，校貓的帽子已經被學生們拍了數千次，已有許多細碎而不起眼的銀芯掉落在地面但無人問津。負責清潔的校工甚是困擾，現學校已將這些銀芯收集起來並完全洗淨存放於失物招領處，請失主自行及時前來認領。"
  },
  Activity_48827_ActivityTips = {
    Text = "<Title:簡介>\n據不完全統計，在這半年以來，校貓的帽子已經被學生們拍了數千次，許多細碎而不起眼的銀芯掉落在地面但無人問津。負責清潔的校工甚是困擾，現學校已將這些銀芯收集起來並完全洗淨存放於失物招領處，請失主自行前來認領。\n\n<Title:活動規則>\n·活動期間，守密人每天登入後可以在「帽中的銀芯」中領取「銀芯」×1000，最多可以領取 5 次。\n·獎勵將根據守密人累計登入依次解鎖，當日登入獎勵將在9點（GMT+8）刷新。"
  },
