  Activity_51127_ActivityName = {
    Text = "故事的魔法·輕量復刻"
  },
  Activity_51127_ActivityPlot = {
    Text = "朵爾交代的任務，從來都不簡單。\n即便她數次提醒大家「要玩得開心」，可首次帶著一群喚醒體出門，守密人怎麼能不膽戰心驚？\n但，要記得「玩得開心」哦。"
  },
  Activity_51127_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「魔法劇本商店」"
  },
  Activity_51127_ActivityTips = {
    Text = "<Title:活動簡介>\n1、玩法活動復刻「故事的魔法」限時開放，守密人可透過「魔法劇本商店」和「成就獎勵」再次獲得活動限定命輪「35mm 的魔法」與活動限定頭像「以銀鑰之名：莉莉」！\n2、活動期間，「特遣紀錄：故事的魔法」將限時免費解鎖。\n\n<Title:活動時間>\n1、6 月 3 日 9：00 - 6 月 17 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、6 月 17 日 9：00 - 6 月 24 日 9：00（GMT+8），僅保留「魔法劇本商店」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title:劇本迷思>\n1、「劇本迷思」包含 9 個素材關卡，每天自動開放 1 個，開放後需通關前置特遣紀錄關卡才可挑戰。\n2、每次挑戰將消耗 60 點靈啡肽，挑戰成功將獲得活動貨幣「飄零的靈感」和培養素材；本次活動素材關卡通關後即可支援重現。\n3、可以使用校友會助戰和「共鳴：導演密碼」來幫助你更輕鬆地通關。\n\n<Title:靈感加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「劇本迷思」關卡任務報酬中的「飄零的靈感」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「莉莉」：啟靈0/1/2/3及以上，加成20％/30％/40％/50％\n·SSR命輪「跨越疼痛」：疊位0/1/2/3及以上，加成20％/30％/40％/50％\n·SR命輪「35mm的魔法」：疊位0/1/2/3及以上，加成20％/30％/40％/50％\n2、不同喚醒體或命輪的「靈感加成」以疊加的方式結算。\n\n<Title:共鳴：導演密碼>\n1、守密人可以透過完成活動成就獲取「演繹之心」。 \n2、消耗「演繹之心」，啟動「共鳴：導演密碼」，可以讓守密人在活動玩法「劇本迷思」和「特遣紀錄：故事的魔法」中變得更強，還可以提升完成「劇本迷思」挑戰後獲得的「飄零的靈感」和同調率獎勵。\n\n<Title:成就獎勵>\n1、完成成就任務可以獲得活動限定頭像「以銀鑰之名：莉莉」、活動貨幣「飄零的靈感」、銀芯。\n2、包含 25 個任務：通關「劇本迷思」的每個關卡 1 次、使用每個界域隊伍通關「劇本迷思」 1/2 次、通關「特遣紀錄：故事的魔法」每個調查事件 1 次、完成所有活動成就。\n\n<Title:特遣紀錄>\n1、活動期間，「特遣紀錄：故事的魔法」可免費解鎖。\n2、在「特遣紀錄：故事的魔法」中，守密人將使用包含劇情預設「莉莉」的特殊編隊進行挑戰。\n\n<Title:復刻補償>\n1、此前已經解鎖「特遣紀錄：故事的魔法」的守密人，在本次復刻活動期間重新解鎖時將會獲得「飄零的靈感」×1000的補償。\n此前已經獲得活動限定頭像「以銀鑰之名：莉莉」的守密人，重複獲得時將自動轉換為「飄零的靈感」×3000。\n此前已經獲得啟動共鳴材料「演繹之心」的守密人，每獲得 1 個多餘的「演繹之心」將自動轉換為「薔薇金券」×5000。\n"
  },
  Activity_51127_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_51611_ActivityTips = {
    Text = "<Title:參與條件>\n·完成「調查行動」2-9·普通後可參與。\n<Title:調查事件>\n·活動期間，每天會推出「故事的魔法」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「故事的魔法」的調查進度會保留，守密人可以在特遣紀錄中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「故事的魔法」普通模式和完成「故事的魔法」的調查事件後，可以獲得無垢之芯、賢者之石和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
