  Activity_52040_ActivityName = {
    Text = "沉淵之祀"
  },
  Activity_52040_ActivityPlot = {
    Text = "深海的倒影上，王的夢境消散，神的國度也已腐朽。\n她從舊日的幻夢中走來，走入未來坍塌的廢墟。\n她詢問深淵，深淵緘默不語。\n她向深淵祭祀，回應她的，只有她自己。"
  },
  Activity_52040_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「沉淵的回應」"
  },
  Activity_52040_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「神國誕臨」、「王的諭旨」和「成就獎勵」收集活動貨幣，活動貨幣可在「沉淵的回應」中用於進獻從而獲得道具獎勵，包括活動限定SR命輪「深海的呼喚」、賢者之石、無垢之芯、流明之芯等。\n2、活動期間「異夢視界：褻瀆」將免費開放。\n\n<Title:活動時間>\n1、6 月 17 日 9：00 - 7 月 1 日 9：00（GMT+8），所有活動內容均可參與。\n2、7 月 1 日 9：00 - 7 月 8 日 9：00（GMT+8），僅保留「沉淵的回應」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 神國誕臨>\n1、「神國誕臨」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣「祀者之淚」、「祀者之血」和「祀者之髓」。雙倍挑戰時，需要消耗 240 靈啡肽，關卡任務報酬也會翻倍，同調率獎勵不變。\n3、「成就獎勵」完成度達到100%之後，解鎖已通關關卡的「重現」功能。每次「重現」消耗 「靈啡肽」× 120 。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：海淵祭儀」來幫助你更輕鬆地通關。\n\n<Title: 祀物加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「神國誕臨」關卡任務報酬中的「祀者之淚」、「祀者之血」和「祀者之髓」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「彌利亞姆」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「虔誠的偉力」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「深海的呼喚」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「祀物加成」以疊加的方式結算。\n\n<Title:共鳴：海淵祭儀>\n1、守密人可以透過完成活動成就獲取「虔信之心」。 \n2、消耗「虔信之心」，啟動「共鳴：海淵祭儀」，可以獲得以下加成：\n（1）讓守密人在活動玩法「神國誕臨」中變得更強，挑戰更加輕鬆。\n（2）提升完成「神國誕臨」挑戰後獲得的活動貨幣。\n（3）啟動活動玩法「王的諭旨」。\n\n<Title: 王的諭旨>\n·啟動共鳴「祭獻試煉」後，每小時自動獲得60「祀者之淚」，最多儲存 25 小時。\n\n<Title: 沉淵的回應>\n1、「沉淵的回應」共有三個祭壇，開啟時間如下：\n·「瑩淚祭壇」： 6 月 17 日 9 時開啟。\n·「猩血祭壇」： 6 月 19 日 9 時開啟。\n·「靈髓祭壇」： 6 月 21 日 9 時開啟。\n2、每次進獻祭品將消耗 500「祀者之淚」/「祀者之血」/「祀者之髓」，隨機獲得祭壇中的五個物品獎勵。\n3、每個祭壇的物品獎勵分為「神國的恩賜」和「凡庸的獎賞」兩種，重置時可以使指定物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「神國的恩賜」無剩餘數量後，守密人可以選擇重置，重置後會將「神國的恩賜」和「凡庸的獎賞」的剩餘數量重置至上限；也可以選擇繼續進獻祭品，當「凡庸的獎賞」也無剩餘數量後，須進行重置才可以繼續進獻祭品。\n（2）第3次開始重置：當「凡庸的獎賞」無剩餘數量後才可以進行重置，重置會將「凡庸的獎賞」的剩餘數量重置至上限，「神國的恩賜」不再重置。\n\n<Title: 異夢視界>\n1、「異夢視界」是全新的調查類型，相比通常的劇情演繹形式，「異夢視界」的將更側重文字的表現，文字內容量也更多。\n2、在「異夢視界：褻瀆」中，你將透過與彌利亞姆精神的連結，直接讀取她的記憶，從而見證：尚為孩童的彌利亞姆一步步經歷利莫里亞的苦難，在信仰中迷茫，在信仰中掙扎，最終走上了成為救世主與毀滅者的道路……\n3、活動期間「異夢視界：褻瀆」將免費開放。每隔2天會推出新的事件，通關「異夢視界：褻瀆」後可以在成就獎勵中獲得銀芯、活動限定SR命輪「深海的呼喚」等獎勵，成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n4、活動結束後，「異夢視界：褻瀆」的調查進度會保留，如果活動期間未解鎖「異夢視界：褻瀆」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n5、無論是否在活動期間，通關「異夢視界：褻瀆」後都可以獲得「鑰令：海之祭」。\n\n\n\n"
  },
  Activity_52040_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_53727_ActivityTips = {
    Text = "<Title:活動簡介>\n·「返校日」任務分為4組，分別在活動開啟第1、2、3、4天解鎖。\n·守密人可以透過完成「返校日」任務獲得「返校邀約」。\n·使用「返校邀約」可以在「返校商店」中兌換豐厚獎勵。"
  },
  Activity_53728_ActivityTips = {
    Text = "<Title:活動簡介>\n·「助力新程」活動期間，守密人通關「製劑淬煉」「渾濁殘像」「海淵殘像」「器質殘像」「維度殘像」「混沌集群」「波納佩之墟」「蠕蟲之所」「史瓦西喉」後，「薔薇金券」和素材獎勵將會翻倍，每天總共可享受6次。\n·當日未使用完畢的雙倍獎勵次數將在次日9點（GMT+8）清空，請守密人記得及時使用喔~"
  },
  Activity_53729_ActivityName = {
    Text = "返校報到"
  },
  Activity_53729_ActivityTips = {
    Text = "<Title:活動簡介>\n·守密人每天登入後可以在「返校報到」中領取當日簽到獎勵。\n·獎勵將根據守密人累計登入依次解鎖，當日簽到獎勵將在9點（GMT+8）刷新。"
  },
  Activity_53829_ActivityName = {
    Text = "與薔薇書"
  },
  Activity_53829_ActivityPlot = {
    Text = "華麗的金鑽，耀眼的珠光……\n無數浮華的裝點為她贏得了女皇般虛妄的想像\n現在，她決心將這份虛妄維持到永遠。"
  },
  Activity_53829_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「金紅慶典」"
  },
  Activity_53829_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「薔薇憶事」和「成就獎勵」收集活動貨幣「通靈鳥羽扇」，「通靈鳥羽扇」可在「金紅慶典」中兌換豐厚獎勵，包括活動限定SR命輪「百萬蒙寵之眼」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間，完成「成就獎勵」的任務可獲得活動限定頭像「以銀鑰之名：索蕾爾」、活動限定SR命輪「百萬蒙寵之眼」、銀芯和大量活動貨幣「通靈鳥羽扇」。\n3、活動期間，「特遣紀錄：薔薇禮讚」將免費開放。\n\n<Title:活動時間>\n1、7 月 1 日 9：00 - 7 月 15 日 9：00（GMT+8），所有活動內容均可參與。\n2、7 月 15 日 9：00 - 7 月 22 日 9：00（GMT+8），僅保留「金紅慶典」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 薔薇憶事>\n1、「薔薇憶事」包含 9 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰不同的關卡除了獲得不同的素材掉落外，還將獲得活動貨幣「通靈鳥羽扇」。\n3、本次活動關卡為直接戰鬥的素材關卡，通關後可重現！每次「重現」消耗 「靈啡肽」× 120 。\n4、請注意：使用「重現」功能時，無法獲得同調率。\n\n<Title: 羽扇加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「薔薇憶事」關卡任務報酬中的「通靈鳥羽扇」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「索蕾爾」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「以薔薇之名」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「百萬蒙寵之眼」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「羽扇加成」以疊加的方式結算。\n\n<Title:特遣紀錄>\n1、活動期間，此前已經解鎖「特遣紀錄：薔薇禮讚」的守密人，重新解鎖將會獲得「通靈鳥羽扇」×600的補償。\n2、在「特遣紀錄：薔薇禮讚」中，守密人將使用包含劇情預設「索蕾爾」的特殊編隊進行挑戰。"
  },
  Activity_53829_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_54375_ActivityName = {
    Text = "薔薇禮讚"
  },
  Activity_54375_ActivityPlot = {
    Text = "女士們，先生們。\n溫和的良夜已經拉開帷幕，準備好手邊的佳釀吧。\n這是一個漫長的故事，且聽我們慢慢道來……"
  },
  Activity_54375_ActivityTips = {
    Text = "<Title:參與條件>\n·完成「調查行動」2-9·普通後可參與。\n<Title:調查事件>\n·活動期間，每天會推出「薔薇禮讚」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「薔薇禮讚」的調查進度會保留，守密人可以在特遣紀錄中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「薔薇禮讚」普通模式和完成「薔薇禮讚」的調查事件後，可以獲得無垢之芯、賢者之石和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
  Activity_54402_ActivityTips = {
    Text = "<Title:活動規則>\n·「分裂患者·混沌」活動開啟期間，守密人可使用包含「24」的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
