  Activity_54596_ActivityName = {
    Text = "智識贈禮"
  },
  Activity_54596_ActivityTips = {
    Text = "<Title:活動簡介>\n1、守密人完成活動指定任務後，可領取「原質樂園」、「輪轉之書」、「原型視界」、「循環母版」、「靈魂回溯之芯」、「命途回溯之芯」，以及「忘卻篇」限定喚醒體與命輪、「星辰篇」限定喚醒體與命輪等豐厚獎勵，更有活動限定頭像框「銀白之矩」、守密人經驗加速等專屬獎勵！\n2、本活動永久開放。完成活動中所有任務並領取完獎勵後，第二天9：00（GMT+8）後本活動結束並不再展示。\n\n<Title:至高禮讚>\n1、完成活動指定任務可獲得「至高禮讚」效果，使守密人經驗獲得加速，最高可達 100%。多個「至高禮讚」效果同時存在時，取最高的加速效果。\n2、解鎖或獲得更高級的「至高禮讚」效果時，會按照加速比例和當前可被加速的守密人經驗總量，立即獲得額外的守密人經驗。\n3、解鎖「至高禮讚」後，守密人每次獲得守密人經驗時，都將獲得對應加速比例的額外守密人經驗。\n4、請注意，「至高禮讚」帶來的額外守密人經驗不會計入可被加速的守密人經驗總量。\n5、當前可被加速的守密人經驗總量：{s1}。\n6、加速已累計獲得額外守密人經驗：{s2}（{s3}%）。"
  },
  Activity_55110_ActivityPlot = {
    Text = "少女們的笑聲響起，迴盪在大火尚未燃起的花園。\n為這美麗的往昔駐足吧，我的朋友。\n聽尚未凋零的春天，輕聲講述過去的故事。"
  },
  Activity_55110_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「柯蕾特的花房」"
  },
  Activity_55110_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「花園往事」、「繆斯之吻」和「成就獎勵」收集三種「詩文」，「詩文」可在「柯蕾特的花房」中用於交換從而獲得道具獎勵，包括活動限定SR命輪「往昔的花與詩」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間「特遣紀錄：玫瑰的棲居」將免費開放。\n\n<Title:活動時間>\n1、7 月 15 日 9：00 - 7 月 29 日 9：00（GMT+8），所有活動內容均可參與。\n2、7 月 29 日 9：00 - 8 月 5 日 9：00（GMT+8），僅保留「柯蕾特的花房」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 花園往事>\n1、「花園往事」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣「惆悵的詩文」、「遺憾的詩文」和「歡欣的詩文」。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：花園挽歌」來幫助你更輕鬆地通關。\n5、關卡解鎖後第2天，解鎖該關卡的癲狂難度。完成癲狂難度首通可獲得豐厚的活動貨幣獎勵。\n6、請注意：癲狂難度挑戰不消耗靈啡肽，不可重現，且首通後重複挑戰不會再獲得活動貨幣獎勵。\n\n<Title: 詩文加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「花園往事」關卡任務報酬中的「惆悵的詩文」、「遺憾的詩文」和「歡欣的詩文」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「奧爾拉」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「詩箋的句尾」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「往昔的花與詩」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「詩文加成」以疊加的方式結算。\n3、特別的，癲狂難度首通挑戰獎勵不會受到「詩文加成」影響。\n\n<Title:共鳴：花園挽歌>\n1、守密人可以透過完成活動成就獲取「灰燼之心」。 \n2、消耗「灰燼之心」，激活「共鳴：花園挽歌」，可以獲得以下加成：\n（1）讓守密人在活動玩法「花園往事」中變得更強，挑戰更加輕鬆。\n（2）提升完成「花園往事」挑戰後獲得的活動貨幣。\n（3）激活活動玩法「繆斯之吻」。\n\n<Title: 繆斯之吻>\n·激活共鳴「萬物生長」後，每小時自動獲得60「惆悵的詩文」，最多儲存 25 小時。\n·激活共鳴「以詩換花」後，「繆斯之吻」每小時可額外獲得60「遺憾的詩文」。\n\n<Title: 柯蕾特的花房>\n1、「柯蕾特的花房」共有三個花圃，開啟時間如下：\n·「鳶尾花圃」： 7 月 15 日 9 時開啟。\n·「桔梗花圃」： 7 月 17 日 9 時開啟。\n·「薔薇花圃」： 7 月 19 日 9 時開啟。\n2、每次交換將消耗 1000「惆悵的詩文」/「遺憾的詩文」/「歡欣的詩文」，隨機獲得花圃中的五個物品獎勵。\n3、每個花圃的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n4、8 月 5 日 9：00（GMT+8）後，剩餘未交換的「詩文」將按照每200個兌換「薔薇金券×5000」的比例進行回收，請守密人注意查收郵件。\n\n<Title: 特遣紀錄>\n1、活動期間「特遣紀錄：玫瑰的棲居」將免費開放。每隔2天會推出新的事件，通關「特遣紀錄：玫瑰的棲居」後可以在成就獎勵中獲得銀芯、活動限定SR命輪「往昔的花與詩」等獎勵，成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n2、活動結束後，「特遣紀錄：玫瑰的棲居」的調查進度會保留，如果活動期間未解鎖「特遣紀錄：玫瑰的棲居」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「特遣紀錄：玫瑰的棲居」後都可以獲得「鑰令：春天的獻詩」。"
  },
