  Activity_56429_ActivityTips = {
    Text = "<Title:活動簡介>\n活動期間，守密人可透過限時玩法「虛無之門」和「成就獎勵」收集活動貨幣「人偶零件」，「人偶零件」可在「師長的教誨」中換取獎勵，包括活動限定SR命輪「牧羊人的手杖」、流明之芯、無垢之芯、賢石碎屑、擬態凝晶等。\n\n<Title:虛無之門>\n1、「虛無之門」包含 9 個無需探索直接戰鬥的素材關卡，每天開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得培養素材和活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title:人偶零件加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「虛無之門」關卡任務報酬中的「人偶零件」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「熔毀·朵爾」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「墜入虛無的人偶」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「牧羊人的手杖」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「人偶零件加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title: 師長的教誨>\n1、每次「交換零件」將消耗 750「人偶零件」，隨機獲得「師長的教誨」中的五個物品獎勵。\n2、「師長的教誨」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 5 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 6 次及之後重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動時間>\n1、2 月 17 日 9：00 - 3 月 3 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、3 月 3 日 9：00 - 3 月 10 日 9：00（GMT+8），僅保留「師長的教誨」和「成就獎勵」，其他內容均已結束不可參與。\n3、3 月 10 日 9：00（GMT+8）後，剩餘未兌換的「人偶零件」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
