  Activity_56431_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「聖胎孵化」"
  },
  Activity_56431_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「黑暗子宮」和「成就獎勵」收集三種「胚胎」，「胚胎」可在「聖胎孵化」中兌換道具獎勵，包括活動限定SR命輪「冰川下的沉眠」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間，完成「成就獎勵」的任務可獲得活動限定頭像「以銀鑰之名：戈利亞」、活動限定SR命輪「冰川下的沉眠」和大量「胚胎」。\n\n<Title:活動時間>\n1、7 月 29 日 9：00 - 8 月 12 日 9：00（GMT+8），所有活動內容均可參與。\n2、8 月 12 日 9：00 - 8 月 19 日 9：00（GMT+8），僅保留「聖胎孵化」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 黑暗子宮>\n1、「黑暗子宮」包含 7 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣「無識之胚」、「無欲之胚」和「無厭之胚」。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n5、通關關卡任意難度後，解鎖該關卡的癲狂難度。完成癲狂難度首通可獲得豐厚的活動貨幣獎勵。\n6、請注意：癲狂難度挑戰不消耗靈啡肽，不可重現，且首通後重複挑戰不會再獲得活動貨幣獎勵。\n\n<Title: 胚胎加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「黑暗子宮」關卡任務報酬中的「無識之胚」、「無欲之胚」和「無厭之胚」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「墨菲」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「隱秘的誕生」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「冰川下的沉眠」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「胚胎加成」以疊加的方式結算。\n3、特別的，癲狂難度首通挑戰獎勵不會受到「胚胎加成」影響。\n\n<Title: 聖胎孵化>\n1、「聖胎孵化」僅在 7 月 29 日 9：00 - 8 月 19 日 9：00（GMT+8）期間開放。\n2、8 月 19 日 9：00（GMT+8）後，剩餘未兌換的「胚胎」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
