  Activity_56433_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「月夜傳說」和「成就獎勵」收集活動貨幣「決勝籌碼」，「決勝籌碼」可在「好運俱樂部」中兌換豐厚獎勵，包括活動限定SR命輪「命運輪盤賭」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間，完成「成就獎勵」的任務可獲得活動限定頭像「以銀鑰之名：萊克」、活動限定SR命輪「命運輪盤賭」、銀芯和大量活動貨幣「決勝籌碼」。\n3、活動期間，「特遣紀錄：狩獵愉快！」將免費開放。\n\n<Title:活動時間>\n1、8 月 12 日 9：00 - 8 月 26 日 9：00（GMT+8），所有活動內容均可參與。\n2、8 月 26 日 9：00 - 9 月 2 日 9：00（GMT+8），僅保留「好運俱樂部」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 月夜傳說>\n1、「月夜傳說」包含 9 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰不同的關卡除了獲得不同的素材掉落外，還將獲得活動貨幣「決勝籌碼」。\n3、本次活動關卡為直接戰鬥的素材關卡，通關後可重現！每次「重現」消耗 「靈啡肽」× 120 。\n4、請注意：使用「重現」功能時，無法獲得同調率。\n\n<Title: 籌碼加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「月夜傳說」關卡任務報酬中的「決勝籌碼」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「萊克」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「好運時間」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「命運輪盤賭」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「籌碼加成」以疊加的方式結算。\n3、特別的，癲狂難度首通挑戰獎勵不會受到「籌碼加成」影響。\n\n<Title: 好運俱樂部>\n1、「好運俱樂部」僅在 8 月 12 日 9：00 - 9 月 2 日 9：00（GMT+8）期間開放。\n2、9 月 2 日 9：00（GMT+8）後，剩餘未兌換的「決勝籌碼」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。\n\n<Title:特遣紀錄>\n1、在「特遣紀錄：狩獵愉快！」中，守密人將使用包含劇情預設「萊克」的特殊編隊進行挑戰。\n2、通關「特遣紀錄：狩獵愉快！」可獲得全新鑰令「鑰令：一聲槍響」。"
  },
