  },
  Activity_56434_ActivityPlot = {
    Text = "無人知曉她在門扉前靜默的年歲。\n她本無意投身任何一個具象世界，不應為任何時空連續體裹挾精神，不容任何事物擾動窮極之門的平穩。\n直到她與你的目光相觸的剎那。"
