  Activity_61156_ActivityName = {
    Text = "終焉紀行"
  },
  Activity_61156_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「終焉紀行」中領取獎勵。\n2、「終焉紀行」永久開放。\n3、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_61369_ActivityName = {
    Text = "漸進樂律"
  },
  Activity_61369_ActivityPlot = {
    Text = "守密人可以從以下限定命輪中任選其一喚醒！"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:簡介>\n黑池波雲詭譎，命輪往復流轉，在哈姆林的樂音牽引下，無限樂律齊奏，匯成你所跋涉的歷程之命輪。願它們的助力能陪伴你直至終末奏鳴的休止符。\n\n<Title:活動規則>\n·活動期間只需登入一天，即可在以下12個限定命輪中任選其一喚醒，包括：「神王的頌歌」、「至為珍貴的藏品」、「以薔薇之名」、「跨越疼痛」、「隱秘的誕生」、「女王的戒律」、「神言石板」、「畸體回噬」、「虔誠的偉力」、「詩箋的句尾」、「慈悲的哺育」、「好運時間」。"
  },
  Activity_61369_BannerText = {
    Text = "限定命輪免費領取"
  },
  Activity_61370_ActivityName = {
    Text = "純銀的初心"
  },
  Activity_61370_ActivityPlot = {
    Text = "每日登入可領取紀念限定SSR命輪「純銀之心」，總計可領取16個！"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:簡介>\n無論世界如何傾覆，只要每個人都守護著最初的、澄澈的純銀之心，故事終會往復循環，新的生命將在荒蕪的大地上重新誕生。\n\n<Title:活動規則>\n·活動期間，守密人每天登入後可以在「純銀的初心」中領取紀念限定 SSR 命輪「純銀的初心」，總計可領取 16 次。\n·獎勵將根據守密人累計登入依次解鎖，當日登入獎勵將在9點（GMT+8）刷新。"
  },
  Activity_61370_BannerText = {
    Text = "限定SSR命輪免費領取"
  },
  Activity_61371_ActivityName = {
    Text = "六翼滿開之願"
  },
  Activity_61371_ActivityPlot = {
    Text = "黑池動盪之中，來自無限維度的銀芯通過維度罅隙散落在黑池之畔。塔薇將它們悉心收攏，置於黑池一角。縱然這些銀芯不能阻止融蝕蔓延，但其中蘊藏的思念與心意永遠光華璀璨。"
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:簡介>\n黑池動盪之中，來自無限維度的銀芯通過維度罅隙散落在黑池之畔。塔薇將它們悉心收攏，置於黑池一角。縱然這些銀芯不能阻止融蝕蔓延，但其中蘊藏的思念與心意永遠光華璀璨。\n\n<Title:活動規則>\n·活動期間，守密人每天登入後可以在活動中領取「銀芯」× 1000，最多可以領取 6 次。\n·活動期間，守密人累計登入第 7 天，更可直接領取當期限定喚醒體「塔薇」！\n·獎勵將根據守密人累計登入依次解鎖，當日登入獎勵將在9點（GMT+8）刷新。"
  },
  Activity_61371_BannerText = {
    Text = "簽到領取超多銀芯"
  },
