  Activity_65387_ActivityName = {
    Text = "校貓的歉意"
  },
  Activity_65387_ActivityPlot = {
    Text = "近期由於校方防護措施漏洞，導致<Del:「臨時文本、紅點」>融蝕侵擾校園的情況越來越多，為廣大學子帶來了諸多不便。因此校務處特地設立了多處補給點，為同學們發放物資作為補償。（鑑於設施管理失誤的責任，本次補給物資完全由校貓負責搬運。）"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:簡介>\n近期由於校方防護措施漏洞，導致<Del:「臨時文本、紅點」>融蝕侵擾校園的情況越來越多，為廣大學子帶來了諸多不便。因此校務處特地設立了多處補給點，為同學們發放物資作為補償。（鑑於設施管理失誤的責任，本次補給物資完全由校貓負責搬運。）\n\n<Title:活動規則>\n·活動期間，守密人每天登入後可以在「校貓的歉意」中領取「銀芯」× 500，最多可以領取 5 次。\n·獎勵將根據守密人累計登入依次解鎖，當日登入獎勵將在9點（GMT+8）刷新。"
  },
  Activity_65387_BannerText = {
    Text = "簽到領取銀芯"
  },
  Activity_65502_ActivityName = {
    Text = "漸進樂律·雙重奏"
  },
  Activity_65502_ActivityPlot = {
    Text = "守密人可以從以下限定命輪中任選其一喚醒！"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:簡介>\n黑池波雲詭譎，命輪往復流轉，在哈姆林的樂音牽引下，無限樂律齊奏，匯成你所跋涉的歷程之命輪。願它們的助力能陪伴你直至終末奏鳴的休止符。\n\n<Title:活動規則>\n·活動期間只需登入一天，即可在以下12個限定命輪中任選其一喚醒，包括：「神王的頌歌」、「至為珍貴的藏品」、「以薔薇之名」、「跨越疼痛」、「隱秘的誕生」、「女王的戒律」、「神言石板」、「畸體回噬」、「虔誠的偉力」、「詩箋的句尾」、「慈悲的哺育」、「好運時間」。"
  },
  Activity_65502_BannerText = {
    Text = "限定命輪免費領取"
  },
  Activity_65521_ActivityName = {
    Text = "調查補給禮盒"
  },
  Activity_65521_ActivityPlot = {
    Text = "彌薩格校務處提供的調查補給。由阿利斯泰爾自黑池的漂浮物中提煉而來。"
  },
