  Activity_66375_ActivityName = {
    Text = "決勝：原初之影"
  },
  Activity_66375_ActivityPlot = {
    Text = "祂的目光掠過萬千維度，與祂對視的，是萬千銀色的身影。 \n他們渺小，脆弱。他們為銘記而戰，至死方休。"
  },
  Activity_66375_ActivityStageEndContent = {
    Text = "活動已達成，可前往繼續調查。"
  },
  Activity_66375_ActivityTips = {
    Text = "<Title: 共戰原初>\n·「共戰原初」包含 7 個不可重現、直接挑戰原初之視的關卡，活動首日開放前 3 個，之後每 3 天開放 1 個。\n·每次挑戰戰勝對應的原初之視後，即可獲得對應獎勵。\n·每種原初之視均有大量分身，每當某個種類的原初之視被任何守密人挑戰勝利時，該類型原初之視的「世界殘餘數量」就會減少 1，當該類型原初之視的所有分身被消滅後，相應的關卡就會關閉，無法再次挑戰。\n·所有關卡都受到「融災黑潮·終末」的影響，但是每個關卡會提供不同的「純銀之芯」造物，將會為你提供強大的加成。此外，每個關卡還會提供「全知之眼」造物，將使塔薇在戰鬥開始時獲得 120 狂氣，塔薇所有造成的傷害、護盾、回復生命效果提高 50%。\n·所有關卡必須選擇助戰，整個活動中，每個互相關注的守密人只能為你提供一次助戰。由於使用助戰，因此實際同調率獎勵會在獎勵基礎上再提高 50%。\n·守密人需要至少完成調查行動 2-9 才可以參與該活動。\n\n<Title:調查行動：終章>\n·每種原初之視的本體仍然需要在調查行動 9-5 至 9-11 中由你自己來擊敗。這些特殊關卡沒有成就、沒有星數，也沒有「全知之眼」造物的幫助、也無法使用助戰，同時更加困難。\n·在「共戰原初」活動結束後即可解鎖「調查行動：終章」的後續關卡。與其他守密人共同消滅各種原初之視的所有分身後，可以提前解鎖調查行動 9-5 至 9-11 中對應的關卡。"
  },
  Activity_66375_BannerText = {
    Text = "特別活動限時開啟！"
  },
  Activity_66908_ActivityName = {
    Text = "豐穰之息"
  },
  Activity_66908_ActivityTips = {
    Text = "<Title:活動規則>\n·「豐穰之息」活動開啟期間，守密人可使用包含泰旖絲的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_67077_ActivityName = {
    Text = "歷程追思獻禮Ⅸ"
  },
  Activity_67077_ActivityPlot = {
    Text = "一段記憶塵封歸檔，一段歷程載入過往。追思之時，勿忘獻上崇敬之禮。"
  },
  Activity_67718_ActivityName = {
    Text = "在春天凋零以前·復刻"
  },
  Activity_67718_ActivityPlot = {
    Text = "少女們的笑聲響起，迴盪在大火尚未燃起的花園。\n為這美麗的往昔駐足吧，我的朋友。\n聽尚未凋零的春天，輕聲講述過去的故事。"
  },
  Activity_67718_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「柯蕾特的花房」"
  },
  Activity_67718_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可通過限時玩法「花園往事」、「繆斯之吻」和「成就獎勵」收集三種「詩文」，「詩文」可在「柯蕾特的花房」中用於交換從而獲得道具獎勵，包括活動限定SR命輪「往昔的花與詩」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間「特遣紀錄：玫瑰的棲居」將免費開放。\n\n<Title:活動時間>\n1、8 月 10 日 9：00 - 9 月 7 日 9：00（UTC+8），所有活動內容均可參與。\n2、9 月 7 日 9：00 - 9 月 14 日 9：00（UTC+8），僅保留「柯蕾特的花房」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 花園往事>\n1、「花園往事」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣「惆悵的詩文」、「遺憾的詩文」和「歡欣的詩文」。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：花園挽歌」來幫助你更輕鬆地通關。\n5、關卡解鎖後第2天，解鎖該關卡的癲狂難度。完成癲狂難度首通可獲得豐厚的活動貨幣獎勵。\n6、請注意：癲狂難度挑戰不消耗靈啡肽，不可重現，且首通後重複挑戰不會再獲得活動貨幣獎勵。\n\n<Title: 詩文加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「花園往事」關卡任務報酬中的「惆悵的詩文」、「遺憾的詩文」和「歡欣的詩文」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「奧爾拉」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「詩箋的句尾」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「往昔的花與詩」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「詩文加成」以疊加的方式結算。\n3、特別的，癲狂難度首通挑戰獎勵不會受到「詩文加成」影響。\n\n<Title:共鳴：花園挽歌>\n1、守密人可以通過完成活動成就獲取「灰燼之心」。 \n2、消耗「灰燼之心」，激活「共鳴：花園挽歌」，可以獲得以下加成：\n（1）讓守密人在活動玩法「花園往事」中變得更強，挑戰更加輕鬆。\n（2）提升完成「花園往事」挑戰後獲得的活動貨幣。\n（3）激活活動玩法「繆斯之吻」。\n\n<Title: 繆斯之吻>\n·激活共鳴「萬物生長」後，每小時自動獲得「惆悵的詩文」× 60，最多儲存 25 小時。\n·激活共鳴「以詩換花」後，「繆斯之吻」每小時可額外獲得「遺憾的詩文」× 60。\n\n<Title: 柯蕾特的花房>\n1、「柯蕾特的花房」共有三個花圃，開啟時間如下：\n·「鳶尾花圃」： 8 月 10 日 9 時開啟。\n·「桔梗花圃」： 8 月 12 日 9 時開啟。\n·「薔薇花圃」： 8 月 14 日 9 時開啟。\n2、每次交換將消耗 「惆悵的詩文」/「遺憾的詩文」/「歡欣的詩文」× 750，隨機獲得花圃中的五個物品獎勵。\n3、每個花圃的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n4、9 月 14 日 9：00（UTC+8）後，剩餘未交換的「詩文」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。\n\n<Title: 特遣紀錄>\n1、活動期間「特遣紀錄：玫瑰的棲居」將免費開放。每隔2天會推出新的事件，通關「特遣紀錄：玫瑰的棲居」後可以在成就獎勵中獲得銀芯、活動限定SR命輪「往昔的花與詩」等獎勵，成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n2、活動結束後，「特遣紀錄：玫瑰的棲居」的調查進度會保留，如果活動期間未解鎖「特遣紀錄：玫瑰的棲居」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「特遣紀錄：玫瑰的棲居」後都可以獲得「鑰令：春天的獻詩」。"
  },
