  Activity_67726_ActivityName = {
    Text = "靈魂的牧人·復刻"
  },
  Activity_67726_ActivityPlot = {
    Text = "他為你們受過苦，擔了你們的劫難。\n因他付出的血肉，你們得了醫治；\n因他付出的生命，你們得了寬恕。"
