  Activity_67726_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「聖堂義賣現場」"
  },
  Activity_67726_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「聖堂之路」、「市民的善意」和「成就獎勵」收集活動貨幣「義賣券」，「義賣券」可在「聖堂義賣現場」中換取隨機商品，包括活動限定SR命輪「鏡中人」、無垢之芯、流明之芯等。\n2、活動期間，「特遣紀錄：血的顏色」將免費開放。完成活動成就還能獲得活動限定頭像「以銀鑰之名：薩爾瓦多」！\n\n<Title:活動時間>\n1、3 月 24 日 9：00 - 4 月 7 日 9：00（GMT+8），所有活動內容均可參與。\n2、4 月 7 日 9：00 - 4 月 14 日 9：00（GMT+8），僅保留「聖堂義賣現場」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title:聖堂之路>\n1、「聖堂之路」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣「義賣券」。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：靈魂的岔路」來幫助你更輕鬆地過關。\n\n<Title:輝光加成>\n1、在「靈魂輝光」的影響下，守密人擁有特定喚醒體或命輪（不要求上陣）可以使可以使「聖堂之路」關卡任務報酬中的「義賣券」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「薩爾瓦多」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「神言石板」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「鏡中人」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「輝光加成」以疊加的方式結算。\n3、特別的，癲狂難度首通挑戰獎勵不會受到「輝光加成」影響。\n\n<Title:共鳴：靈魂的岔路>\n1、守密人可以透過完成活動成就獲取「懺悔之心」。 \n2、消耗「懺悔之心」，啟動「共鳴：靈魂的岔路」，可以獲得以下加成：\n（1）讓守密人在活動玩法「聖堂之路」和「特遣紀錄：血的顏色」中變得更強，挑戰更加輕鬆。\n（2）提升完成「聖堂之路」挑戰後獲得的同調率。\n（3）啟動活動玩法「市民的善意」。\n\n<Title:市民的善意>\n1、啟動共鳴「輕鬆的方式」後，每小時自動獲得60「義賣券」，最多儲存 25 小時。\n2、啟動共鳴「贖罪，贖罪」後，每小時額外自動獲得 1800 薔薇金券。\n\n<Title: 聖堂義賣現場>\n1、「聖堂義賣現場」共有三個商鋪，開啟時間如下：\n·「格雷太太的小店」： 3 月 24 日 9 時開啟。\n·「大約翰的神奇義賣」： 3 月 27 日 9 時開啟。\n·「史密斯特賣」： 3 月 30 日 9 時開啟。\n2、每次交換將消耗 750「義賣券」，隨機獲得商鋪中的五個物品獎勵。\n3、每個商鋪的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n4、4 月 14 日 9：00（GMT+8）後，剩餘未交換的「義賣券」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。\n\n<Title: 特遣紀錄>\n1、活動期間「特遣紀錄：血的顏色」將免費開放。\n2、活動結束後，「特遣紀錄：血的顏色」的調查進度會保留，如果活動期間未解鎖「特遣紀錄：血的顏色」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「特遣紀錄：血的顏色」後都可以獲得「鑰令：神蹟降臨」。\n\n<Title:復刻補償>\n1、此前已經解鎖「特遣紀錄：血的顏色」的守密人，在本次復刻活動期間重新解鎖時將會獲得「義賣券」×700的補償。\n2、此前已經獲得活動限定頭像「以銀鑰之名：薩爾瓦多」的守密人，重複獲得時將自動轉換為 「無形者的請柬」×1。\n3、此前已經獲得啟動共鳴材料「懺悔之心」的守密人，每獲得 1 個多餘的「懺悔之心」將自動轉換為「薔薇金券」×5000。\n"
  },
