  Activity_67731_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「旺達的奇珍寶匣」"
  },
  Activity_67731_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可以透過限時玩法「燃燒的群宴」和「成就獎勵」收集活動貨幣「原生脛骨」、「圓葉菊石」、「螺旋遺跡」。活動貨幣可在「旺達的奇珍寶匣」中購買商品，包括活動限定SR命輪「伊薩拉烏的目光」、流明之芯、無垢之芯等。\n2、活動期間，「意識潛遊：燃燒的群宴」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：旺達」！\n\n<Title:活動時間>\n1、9 月 23 日 9：00 - 10 月 7 日 9：00（GMT+8），所有活動玩法均可參與。\n2、10 月 7 日 9：00 - 10 月 14 日 9：00（GMT+8），僅可參與「旺達的奇珍寶匣」和成就獎勵。\n\n<Title:湖中之城>\n1、「湖中之城」有 7 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗「靈啡肽」× 120，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：代行密令」來幫助你更輕鬆地過關。\n\n<Title:奇珍加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「湖中之城」關卡任務報酬中的活動貨幣獲得額外的掉落加成，具體加成如下：\n·喚醒體「旺達」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「女王的戒律」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「伊薩拉烏的目光」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「奇珍加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「奇珍加成」影響。\n\n<Title:共鳴：代行密令>\n1、守密人可以透過完成活動成就獲取「享樂之心」。\n2、消耗「享樂之心」，啟動「共鳴：代行密令」，可以讓守密人在「湖中之城」中變得更強，挑戰更加輕鬆；也可以讓守密人在通關時獲得額外的活動貨幣。\n\n<Title:意識潛遊>\n1、活動期間，「燃燒的群宴」可免費解鎖。\n2、活動結束後，「燃燒的群宴」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「燃燒的群宴」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「燃燒的群宴」後都可以獲得「鑰令：腐爛盛筵」。\n\n<Title:復刻補償>\n1、此前已經解鎖「意識潛遊：燃燒的群宴」的守密人，在本次復刻活動期間重新解鎖時將會獲得「原生脛骨」×300的補償。\n2、此前已經獲得活動限定頭像「以銀鑰之名：旺達」的守密人，重複獲得時將自動轉換為「原生脛骨」×2000。\n3、此前已經獲得啟動共鳴材料「享樂之心」的守密人，每獲得 1 個多餘的「享樂之心」將自動轉換為「薔薇金券」×5000。\n"
  },
