    Text = "深海的倒影上，王的夢境消散，神的國度也已腐朽。\n她從舊日的幻夢中走來，走入未來坍塌的廢墟。\n她詢問深淵，深淵緘默不語。\n她向深淵祭祀，回應她的，只有她自己。"
