  Activity_67735_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「慾孽滋生」"
  },
  Activity_67735_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「紊亂情慾」和「成就獎勵」收集活動貨幣「豐穰種核」，「豐穰種核」可在「慾孽滋生」中換取獎勵，包括活動限定SR命輪「灼熱的吻別」、流明之芯、無垢之芯、賢石碎屑、擬態凝晶等。\n2、活動期間，「繁衍狂熱」參與條件放寬至通關「調查行動」1-2·普通，且無需滿足喚醒體同調率要求即可解鎖「繁衍狂熱事件」，此外，消耗的「現實起點」數量要求也變為僅需 1 個！\n3、一股神秘力量的到來似乎有助於你與喚醒體建立更深層次的關係，活動期間透過所有方式獲取的同調率翻倍！\n\n<Title:紊亂情慾>\n1、「紊亂情慾」包含 10 個無需探索直接戰鬥的素材關卡，每天開放 1 個。\n2、在這些素材關卡中，你將直接覺醒所有喚醒體，並獲得預設的造物，此外在 6 回合之後受到 1 次泰旖絲的幫助。\n3、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得培養素材和活動貨幣。\n4、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n5、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title:強慾加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「紊亂情慾」關卡任務報酬中的「豐穰種核」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「泰旖絲」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「慈悲的哺育」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「灼熱的吻別」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「強慾加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title: 慾孽滋生>\n1、每次「交換種核」將消耗 750「豐穰種核」，隨機獲得「慾孽滋生」中的五個物品獎勵。\n3、「慾孽滋生」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 4 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 5 次及之後重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動時間>\n1、12 月 15 日 9：00 - 12 月 29 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、12 月 29 日 9：00 - 1 月 5 日 9：00（GMT+8），僅保留「慾孽滋生」和「成就獎勵」，其他內容均已結束不可參與。\n3、1 月 5 日 9：00（GMT+8）後，剩餘未兌換的「豐穰種核」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
