  Activity_67741_ActivityTips = {
    Text = "<Title:活動簡介>\n1、玩法活動復刻「故事的魔法」限時開放，守密人可透過「魔法劇本商店」和「成就獎勵」再次獲得活動限定命輪「35mm 的魔法」與活動限定頭像「以銀鑰之名：莉莉」！\n2、活動期間，「特遣紀錄：故事的魔法」將限時免費解鎖。\n\n<Title:劇本迷思>\n1、「劇本迷思」包含 9 個素材關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：導演密碼」來幫助你更輕鬆地通關。\n\n<Title:靈感加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「劇本迷思」關卡任務報酬中的「飄零的靈感」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「莉莉」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「跨越疼痛」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「35mm的魔法」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「靈感加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title:共鳴：導演密碼>\n1、守密人可以透過完成活動成就獲取「演繹之心」。 \n2、消耗「演繹之心」，啟動「共鳴：導演密碼」，可以讓守密人在活動玩法「劇本迷思」和「特遣紀錄：故事的魔法」中變得更強。\n\n<Title:復刻補償>\n1、此前已經解鎖「特遣紀錄：故事的魔法」的守密人，在本次復刻活動期間重新解鎖時將會獲得「飄零的靈感」×700的補償。\n此前已經獲得活動限定頭像「以銀鑰之名：莉莉」的守密人，重複獲得時將自動轉換為「飄零的靈感」×2000。\n此前已經獲得啟動共鳴材料「演繹之心」的守密人，每獲得 1 個多餘的「演繹之心」將自動轉換為「薔薇金券」×5000。\n\n<Title:活動時間>\n1、1 月 13 日 9：00 - 1 月 27 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、1 月 27 日 9：00 - 2 月 3 日 9：00（GMT+8），僅保留「魔法劇本商店」和「成就獎勵」，其他內容均已結束不可參與。\n3、2 月 3 日 9：00（GMT+8）後，剩餘未兌換的「飄零的靈感」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
