  Activity_67742_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「薔薇憶事」和「成就獎勵」收集活動貨幣「通靈鳥羽扇」，「通靈鳥羽扇」可在「金紅慶典」中兌換豐厚獎勵，包括活動限定SR命輪「百萬蒙寵之眼」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間，完成「成就獎勵」的任務可獲得活動限定頭像「以銀鑰之名：索蕾爾」、活動限定SR命輪「百萬蒙寵之眼」、銀芯和大量活動貨幣「通靈鳥羽扇」。\n3、活動期間，「特遣紀錄：薔薇禮讚」將免費開放。\n\n<Title: 薔薇憶事>\n1、「薔薇憶事」包含 9 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰不同的關卡除了獲得不同的素材掉落外，還將獲得活動貨幣「通靈鳥羽扇」。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title: 羽扇加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「薔薇憶事」關卡任務報酬中的「通靈鳥羽扇」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「索蕾爾」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「以薔薇之名」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「百萬蒙寵之眼」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「羽扇加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title:復刻補償>\n1、活動期間，此前已經解鎖「特遣紀錄：薔薇禮讚」的守密人，重新解鎖將會獲得「通靈鳥羽扇」×700的補償。\n此前已經獲得活動限定頭像「以銀鑰之名：索蕾爾」的守密人，重複獲得時將自動轉換為「通靈鳥羽扇」×2000。\n\n<Title:活動時間>\n1、1 月 27 日 9：00 - 2 月 10 日 9：00（GMT+8），所有活動內容均可參與。\n2、2 月 10 日 9：00 - 2 月 17 日 9：00（GMT+8），僅保留「金紅慶典」和「成就獎勵」，其他內容均已結束不可參與。\n3、2 月 17 日 9：00（GMT+8）後，剩餘未兌換的「通靈鳥羽扇」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
