  Activity_67746_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「最終測試」和「成就獎勵」收集活動貨幣「終末指針」，「終末指針」可在「回聲」中兌換豐厚獎勵，包括活動限定SR命輪「真理之門」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間，完成「成就獎勵」的任務可獲得活動限定頭像「以銀鑰之名：塔薇」、活動限定SR命輪「真理之門」、銀芯和大量活動貨幣「終末指針」。\n\n<Title:活動時間>\n1、11 月 3 日 9：00 - 11 月 17 日 9：00（GMT+8），所有活動內容均可參與。\n2、11 月 17 日 9：00 - 11 月 24 日 9：00（GMT+8），僅保留「回聲」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 最終測試>\n1、「最終測試」包含 9 個關卡，每天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰不同的關卡除了獲得不同的素材掉落外，還將獲得活動貨幣「終末指針」。\n3、本次活動關卡為直接戰鬥的素材關卡，通關後可重現！每次「重現」消耗 「靈啡肽」× 120 。\n4、請注意：使用「重現」功能時，無法獲得同調率。\n\n<Title: 終末指針加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「最終測試」關卡任務報酬中的「終末指針」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「塔薇」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「隱世的轉輪」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「真理之門」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「終末指針加成」以疊加的方式結算。\n3、特別的，癲狂難度首通挑戰獎勵不會受到「終末指針加成」影響。\n\n<Title: 回聲>\n1、「回聲」僅在 11 月 3 日 9：00 - 11 月 24 日 9：00（GMT+8）期間開放。\n2、11 月 24 日 9：00（GMT+8）後，剩餘未兌換的「終末指針」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
