  Activity_68349_ActivityTips = {
    Text = "<Title: 超越星辰·限時預購>\n·本次限時預購活動包含 8 個禮包，其中首個禮包可直接免費領取，第 2-8 個禮包需要購買「超越星辰·限時預購」後方可領取。\n·購買「超越星辰·限時預購」後可立即領取第 2 個禮包獎勵；後續禮包需要分別等待一定時間後才可領取。\n·「超越星辰·限時預購」購買有時間限制，逾期將無法再購買。請守密人酌情購買。"
