  Activity_70438_ActivityName = {
    Text = "烏撒貓貓律"
  },
  Activity_70438_ActivityPlot = {
    Text = "祈歲節將近，所有人都在關注慶典的籌備，並未留意到角落裡漆黑的色塊正在悄悄蠕動，小小囚犯化作液體逃離了牢籠。\n隨著維度的裂隙閃爍，黑色毛團開始分裂......一片片黑色的貓海正在吞噬整個校園！\n你本想對此視而不見，將這種怪異事件交給校務處處理就好。\n但是看在它們會掉落銀芯和金券的份上，你改變了主意。"
  },
  Activity_70438_ActivityTips = {
    Text = "<Title:活動簡介>\n玩法活動「烏撒貓貓律」限時開放！活動期間、守密人可透過「群貓亂舞」暴打校貓、並且可以獲得大量銀芯和薔薇金券！\n\n<Title:活動時間>\n1 月 24 日 9：00 - 2 月 5 日 9：00（UTC+8）、活動期間每天均可參與當天解鎖的「群貓亂舞」關卡、已結束的關卡內容不可再參與。\n\n<Title:群貓亂舞>\n1、「群貓亂舞」一共有 12 個關卡、每天開放不同的關卡、已結束的關卡內容不可再參與。\n2、每次挑戰都不消耗「靈啡肽」、每完成 1 次關卡後可獲得「無垢之芯」、「銀芯」、「薔薇金券」。\n3、本次關卡不可使用校友會助戰。\n4、當天的關卡中、每個喚醒體只能出戰 1 次。\n5、每天的關卡都需要用指定的界域進行挑戰。\n·1 月 24 日：混沌界域\n·1 月 25 日：深海界域\n·1 月 26 日：血肉界域\n·1 月 27 日：超維界域\n·1 月 28 日：不限\n·1 月 29 日：不限\n·1 月 30 日：混沌界域與深海界域\n·1 月 31 日：血肉界域與超維界域\n·2 月 1 日：混沌界域與血肉界域\n·2 月 2 日：深海界域與超維界域\n·2 月 3 日：混沌界域與超維界域\n·2 月 4 日：血肉界域與深海界域"
  },
  Activity_70438_BannerText = {
    Text = "特別活動限時開啟！"
  },
  Activity_71095_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_71095_ActivityTips = {
    Text = "<Title:參與條件>\n·完成「調查行動」2-9·普通後可參與。\n<Title:調查事件>\n·活動期間，每天會推出「故事的魔法」中一個新的調查事件，守密人無需消耗物資即可解鎖進行調查，完成調查事件後可以獲得無垢之芯、調查徽章和守密人經驗等調查獎勵。\n·活動結束後，「故事的魔法」的調查進度會保留，守密人可以在特遣紀錄中消耗融蝕之珠解鎖未解鎖的調查，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。<Title:限時獎勵>\n·活動期間會推出限時獎勵，守密人通關「故事的魔法」普通模式和完成「故事的魔法」的調查事件後，可以獲得無垢之芯、賢者之石和銀芯獎勵！限時獎勵僅在活動期間開啟，活動結束後將無法完成和領取。"
  },
