  Activity_71956_ActivityName = {
    Text = "晉升紀念獻禮Ⅹ"
  },
  Activity_71956_ActivityPlot = {
    Text = "長路漫漫，融蝕晦暗。\n銀鑰之光將指引你我。"
  },
  Activity_71957_ActivityName = {
    Text = "晉升紀念獻禮Ⅸ"
  },
  Activity_71957_ActivityPlot = {
    Text = "長路漫漫，融蝕晦暗。\n銀鑰之光將指引你我。"
  },
  Activity_71982_ActivityName = {
    Text = "靈魂共鳴之禮"
  },
  Activity_71982_ActivityPlot = {
    Text = "你來到校長室，卻發現室內空無一人，似乎那封信只是一場惡作劇。\n就在你打算離開時，視線的一隅瞥見了一個精緻的禮盒，以及貼在上面的留言——致我心愛的你。"
  },
  Activity_71983_ActivityName = {
    Text = "窺見命運之禮"
  },
  Activity_71983_ActivityPlot = {
    Text = "安靜的屋內傳來咔咔聲響，在你上前查看時，敞開的窗戶表明“不速之客”已經離開。\n溫暖的陽光照在桌面多出的禮盒上，娟秀的字體泛起銀光——願命運永遠眷顧於你。"
  },
  Activity_72101_ActivityName = {
    Text = "相位逆轉"
  },
  Activity_72101_ActivityPlot = {
    Text = "“我要讓所有人都玩萬象牌！”\n其他時空的來客因為一場意外進入了相位對弈的空間，將其改造成了與原先大不相同的樣子。\n為了將空間再次逆轉，不同時空的守密人將要決出一位最強者，向這名來客發起挑戰。"
  },
  Activity_72101_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過參與「相位對弈」來完成「成就獎勵」中的成就，並領取「魔法橡果」。\n2、「魔法橡果」可以在「回合奇賞」中領取豐富的獎勵，包括活動限定頭像「逆轉回合：萬象牌」、10個活動限定表情，以及「碎裂餘夢」、「群星餘夢」等。\n3、活動期間「多維連接：逆轉回合」將免費開放！\n4、活動期間，通關了「多維連接：逆轉回合：來自異界的客人」的守密人，「相位對弈」對戰背景會限時替換為「逆轉回合：意識空間」。\n\n<Title: 成就獎勵>\n1、「成就獎勵」中包含了「喚醒體」獲勝成就、「命輪」獲勝成就、「鑰令」獲勝成就、出牌數量成就，守密人可以透過完成成就領取「魔法橡果」。\n2、在「相位對弈」使用不同職業的「喚醒體」每打出25張卡牌即可獲得30個「魔法橡果」。每個職業的「出牌」成就最多可以完成80次。\n3、「喚醒體」成就：每個「喚醒體」在「相位對弈」中完成1/3/6/10次勝利時可以獲得10個「魔法橡果」。\n4、「命輪」成就：每個「命輪」在「相位對弈」中完成1/3/6次勝利時可以獲得10個「魔法橡果」。\n5、「鑰令」成就：每個「鑰令」在「相位對弈」中完成1/3/6次勝利時可以獲得10個「魔法橡果」。\n6、核心課題臨時解鎖的「喚醒體」、「命輪」、「鑰令」將會正常進行勝利計數和出牌計數，但是需要在獲得對應的「喚醒體」、「命輪」、「鑰令」後才能領取勝利成就獎勵。\n\n<Title: 回合奇賞>\n1、守密人累積「魔法橡果」即可領取對應獎勵，累積 2500「魔法橡果」能夠獲得全部核心獎勵，累積 5000「魔法橡果」就可以獲得所有獎勵！\n2、通關「逆轉回合：來自異界的客人」後解鎖積累100-900「魔法橡果」的獎勵，通關「逆轉回合：逆轉萬象的瞬間」後解鎖積累1000-5000「魔法橡果」的獎勵。\n\n<Title: 多維連接>\n1、活動期間「多維連接：逆轉回合」將免費開放。\n2、活動期間，「逆轉回合：貫徹意志的絕對」需要積攢1000「魔法橡果」才能解鎖。\n3、活動結束後，「多維連接：逆轉回合」的調查進度會保留，如果活動期間未解鎖「多維連接：逆轉回合」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「多維連接：逆轉回合」後都可以獲得「鑰令：酒館之門」。\n\n<Title:活動時間>\n本次活動僅在3 月 18 日 9：00 - 4 月 1 日 9：00（GMT+8）期間開放，4 月 1 日 9：00（GMT+8）後活動結束，請各位守密人記得領取「回合奇賞」中的獎勵哦！"
  },
