  Activity_73879_ActivityPlot = {
    Text = "群星正位之刻將至，胸前胎動如鼓。\n折磨她多年的暗夜噩夢，伴隨無數信徒熱淚盈眶的終局到來。\n自祂@1黑暗的@2中，偉大的@3降臨世界。"
