  Activity_78790_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_78791_ActivityName = {
    Text = "雪山消融之時·復刻"
  },
  Activity_78791_ActivityPlot = {
    Text = "艾爾沃斯的冰雪終年不化，正如她的仇恨。\n當未來與過去的雙手交疊，戰士將高舉劍刃，向命運發起復仇的衝鋒。\n當她迎向黑色的浪濤，你是她的旌旗。"
  },
  Activity_78791_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「山巒巨口」"
  },
  Activity_78791_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「野獸雄心」和「成就獎勵」收集三種「花苞」，「花苞」可在「山巒巨口」中用於交換從而獲得道具獎勵，包括活動限定SR命輪「待到雪山消融」、「無垢之芯」、「流明之芯」、「賢石碎屑」、「擬態凝晶」等。\n2、活動期間「特遣紀錄：艾爾沃斯的歸人」將免費開放。\n\n<Title:活動時間>\n1、5 月 19 日 9：00 - 6 月 2 日 9：00（GMT+8），所有活動內容均可參與。\n2、6 月 2 日 9：00 - 6 月 9 日 9：00（GMT+8），僅保留「山巒巨口」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 野獸雄心>\n1、「野獸雄心」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣「寒凍花苞」、「銀霜花苞」和「日光花苞」。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰和「共鳴：吞噬山脈」來幫助你更輕鬆地通關。\n5、關卡解鎖後第2天，解鎖該關卡的癲狂難度。完成癲狂難度首通可獲得豐厚的活動貨幣獎勵。\n6、請注意：癲狂難度挑戰不消耗靈啡肽，不可重現，且首通後重複挑戰不會再獲得活動貨幣獎勵。\n\n<Title: 花苞加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「野獸雄心」關卡任務報酬中的「寒凍花苞」、「銀霜花苞」和「日光花苞」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「血鏈·希洛」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「沉入殷紅」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「待到雪山消融」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「花苞加成」以疊加的方式結算。\n3、特別的，癲狂難度首通挑戰獎勵不會受到「花苞加成」影響。\n\n<Title:共鳴：吞噬山脈>\n1、守密人可以透過完成活動成就獲取「吞噬之心」。 \n2、消耗「吞噬之心」，啟動「共鳴：吞噬山脈」，可以讓守密人在活動玩法「野獸雄心」中變得更強，挑戰更加輕鬆。\n\n<Title: 山巒巨口>\n1、「山巒巨口」共有三個交換商店，開啟時間如下：\n·「吞食的野心」： 5 月 19 日 9 時開啟。\n·「復仇的戰意」： 5 月 21 日 9 時開啟。\n·「重生的希冀」： 5 月 23 日 9 時開啟。\n2、每次交換將消耗 750「寒凍花苞」/「銀霜花苞」/「日光花苞」，隨機獲得交換商店中的五個物品獎勵。\n3、每個交換商店的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 2 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 3 次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n4、6 月 9 日 9：00（GMT+8）後，剩餘未交換的「花苞」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。\n\n<Title: 特遣紀錄>\n1、活動期間「特遣紀錄：艾爾沃斯的歸人」將免費開放。通關「特遣紀錄：艾爾沃斯的歸人」後可以在成就獎勵中獲得活動限定SR命輪「待到雪山消融」等獎勵，成就獎勵僅在活動期間開啟，活動結束後將無法完成和領取。\n2、活動結束後，「特遣紀錄：艾爾沃斯的歸人」的調查進度會保留，如果活動期間未解鎖「特遣紀錄：艾爾沃斯的歸人」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「特遣紀錄：艾爾沃斯的歸人」後都可以獲得「鑰令：群山的覺悟」。"
  },
