  Activity_80312_ActivityName = {
    Text = "療養紀行"
  },
  Activity_80312_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「療養紀行」中領取獎勵。\n2、「療養紀行」永久開放。\n3、解鎖「高級紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「高級紀行」僅在本活動生效。請守密人酌情理性消費。"
