  Activity_81019_ActivityName = {
    Text = "掃除奇旅"
  },
  Activity_81019_ActivityPlot = {
    Text = "是誰穿梭於夢幻的卡達斯，替主人清理垃圾？\n是珈倫~是珈倫！\n清理融蝕~夢境通風~維度消毒~把一切都打掃乾淨~\n畢竟在清掃方面，珈倫我可是專業的！\n主人要來試試麼！珈倫會把清掃之法，毫無保留的教給主人的！"
  },
  Activity_81019_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過參與「掃除進度」並領取「清掃工具」。\n2、「清掃工具」累積到一定數量後可以在「除塵津貼」中領取豐富的獎勵，包括活動限定頭像「清理大師」、銀芯、無垢之芯、賢石碎屑等。\n\n<Title: 掃除進度>\n1、「掃除進度」中包含了多個不同類型的清掃任務，守密人可以透過完成清掃任務來領取「清掃工具」，每日完成所有類型的清掃任務後還有一份額外的獎勵！\n2、活動期間，每首次完成 1 種清掃任務就會播放隱藏劇情。\n3、「掃除進度」會在活動期間的每日 9：00（GMT+8）刷新重置。\n\n<Title: 除塵津貼>\n1、守密人累積「清掃工具」即可領取對應獎勵，每達到 1000「清掃工具」可領取豐厚的物資獎勵，累計達到 10000「清掃工具」可獲得掃除奇旅專屬頭像「清理大師」。\n\n<Title:珈倫的謝禮>\n活動期間，可以在「珈倫的謝禮」處簽到領取珈倫給守密人準備的謝禮！\n\n<Title:活動時間>\n本次活動僅在4 月 28 日 9：00 - 5 月 12 日 9：00（GMT+8）期間開放，5 月 12 日 9：00（GMT+8）後活動結束，請各位守密人記得領取「除塵津貼」中的獎勵哦！"
  },
  Activity_81019_BannerText = {
    Text = "特別活動限時開啟！"
  },
  Activity_81178_ActivityName = {
    Text = "於暴雨中搖曳"
  },
  Activity_81178_ActivityPlot = {
    Text = "驟雨從灰暗的天空中傾斜而下，將海面打得劈啪作響。\n無情的雷光肆意轟鳴，宣示著海面下無邊恐怖的到來。\n輝煌的諾第留斯像蹣跚學步的嬰兒，在波濤狂湧中脆弱地搖曳。\n無人知曉自己的命運將會如何，正如當無常的大海展示它的憤怒時，人們才得以明白，自己是何等渺小。"
  },
  Activity_81178_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「船員的秘寶」"
  },
  Activity_81178_ActivityTips = {
    Text = "<Title:活動簡介>\n活動期間，守密人可透過限時玩法「邃海迷航」和「成就獎勵」收集活動貨幣「信號旗」，「信號旗」可在「船員的秘寶」中換取獎勵，包括活動限定SR命輪「海上領航者」、流明之芯、無垢之芯、賢石碎屑、擬態凝晶等。\n\n<Title:邃海迷航>\n1、「邃海迷航」包含 9 個無需探索直接戰鬥的素材關卡，每天開放 1 個。\n2、每次挑戰將消耗「靈啡肽」× 120，挑戰成功將獲得培養素材和活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title:信號旗加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「邃海迷航」關卡任務報酬中的「信號旗」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「克珀珊特」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「聖火中的指引」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「海上領航者」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「信號旗加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到上述加成影響。\n\n<Title: 船員的秘寶>\n1、每次「交付旗幟」將消耗 750「信號旗」，隨機獲得「船員的秘寶」中的五個物品獎勵。\n2、「船員的秘寶」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 5 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 6 次及之後重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動時間>\n1、5 月 5 日 9：00 - 5 月 19 日 9：00（GMT+8），活動簡介中的所有內容均可參與。\n2、5 月 19 日 9：00 - 5 月 26 日 9：00（GMT+8），僅保留「船員的秘寶」和「成就獎勵」，其他內容均已結束不可參與。\n3、5 月 26 日 9：00（GMT+8）後，剩餘未兌換的「信號旗」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
  Activity_81178_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_81179_ActivityName = {
    Text = "最後的引航"
  },
  Activity_81771_ActivityName = {
    Text = "窺覷神國的陰影"
  },
  Activity_81771_ActivityPlot = {
    Text = "無人窺見神國的聖輝，但從那偶然洩露的真相里，人們能夠感知到神國的陰影。\n它就在那裡，一直在那裡，而無數的虔誠者會讓它真正降臨。\n無論要犯下怎樣深重的罪孽作為代價。"
  },
  Activity_81771_ActivityStageEndContent = {
    Text = "活動已結束"
  },
  Activity_81771_ActivityTips = {
    Text = "<Title: 異動海潮>\n·「異動海潮」包含 7 個關卡、活動首日開放前 3 個、之後每 3 天開放 1 個。每個關卡都有不同的豐厚獎勵！\n·每種「異動海潮」均有大量集群、每當某個種類的集群被任何守密人挑戰勝利時、該類型「異動海潮」的集群數量就會減少 1、當該類型異動海潮的所有集群被消滅後、相應的關卡就會關閉、無法再次挑戰。\n·每位守密人每天最多可以擊退 20 次「異動海潮」集群、活動持續期間每日 9：00（UTC+8）重置次數。\n·每個關卡會提供不同的造物、將會為你提供強大的加成。\n·所有關卡必須選擇助戰、整個活動中、每個互相關注的守密人只能為你提供一次助戰。\n·守密人需要至少完成調查行動 2-9 才可以參與該活動。\n\n<Title: 等級補償>\n·在「窺伺神國的陰影：異動海潮」中有等級補償機制、以便各位守密人能夠共同抵禦入侵！\n等級補償規則如下：\n ·調查隊伍中、等級不足 60 級的喚醒體在本次挑戰中將會補償至 60 級。\n·調查隊伍中、技能等級不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n·調查隊伍中、「瘋狂預兆」不足 6 級的喚醒體在本次挑戰中將會補償至 6 級。\n·調查隊伍中、「靈塑適性」不足 5 級的喚醒體在本次挑戰中將會補償至 5 級。\n ·若守密人等級不足60級、在本次挑戰中將會補償至60級。\n\n<Title:限時任務>\n·活動期間、累計擊退 30 次異動海潮即可完成限時任務、獲得「簡易幻衣繪形券（一期）」×1！\n·在5 月 26 日 9：00 - 6 月 9 日 9：00（UTC+8）期間、可以在「商店：幻衣訂購」使用「簡易幻衣繪形券（一期）」兌換簡約幻衣。\n·更多獲取「簡易幻衣繪形券（一期）」的方式可在社區和公告中了解。"
  },
  Activity_81771_BannerText = {
    Text = "特別活動限時開啟！"
  },
