  Activity_84175_ActivityName = {
    Text = "復律紀行"
  },
  Activity_84175_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「復律紀行」中領取獎勵。\n2·任務分為多組，在活動開啟後每日解鎖一組。\n3、解鎖「復律紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「復律紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_84176_ActivityName = {
    Text = "時絏紀行"
  },
  Activity_84176_ActivityTips = {
    Text = "活動規則：\n1、守密人完成指定的紀行任務後，可以在「時絏紀行」中領取獎勵。\n2·任務分為多組，在活動開啟後每日解鎖一組。\n3、解鎖「時絏紀行」後，完成任務後可額外領取獎勵。\n4、請注意：在本活動中解鎖的「時絏紀行」僅在本活動生效。請守密人酌情理性消費。"
  },
  Activity_89008_ActivityName = {
    Text = "縈迴維度的追隨"
  },
  Activity_89008_ActivityPlot = {
    Text = "她穿行過無數的維度、無數的世界，經歷過無數的希望與絕望，但她不會停下腳步。因為，她明確知曉自己目的地——有你的地方。"
  },
  Activity_89008_ActivityTips = {
    Text = "<Title:簡介>\n1、活動期間，守密人每天登入後可以在「縈迴維度的追隨」中領取當日簽到獎勵。\n2、獎勵將根據守密人累計登入依次解鎖，當日簽到獎勵將在9點（GMT+8）刷新。\n\n<Title:限時任務>\n·活動期間，累計登入 7 天即可完成限時任務，獲得「簡易幻衣繪形券（一期）」×1！\n·在5 月 26 日 9：00 - 6 月 9 日 9：00（GMT+8）期間，可以在「商店：幻衣訂購」使用「簡易幻衣繪形券（一期）」兌換簡約幻衣。\n·更多獲取「簡易幻衣繪形券（一期）」的方式可在社區和公告中了解。"
  },
  Activity_89008_BannerText = {
    Text = "簽到領取超多無垢之芯"
  },
  Activity_89576_ActivityName = {
    Text = "願希望再度萌芽"
  },
  Activity_89576_ActivityPlot = {
    Text = "每日登入可領取紀念限定SSR命輪「重生於湮土」，總計可領取16個！"
  },
  Activity_89576_ActivityTips = {
    Text = "<Title:簡介>\n世界在崩毀。在這樣的世界裡，絕望是常態，痛苦是常態。我必須習慣。但是……仍有溫暖蟄伏於我的心臟，等待著破胸而出。\n\n<Title:活動規則>\n·活動期間，守密人每天登入後可以在「願希望再度萌芽」中領取紀念限定 SSR 命輪「重生於湮土」，總計可領取 16 次。\n·獎勵將根據守密人累計登入依次解鎖，當日登入獎勵將在9點（GMT+8）刷新。"
  },
  Activity_89576_BannerText = {
    Text = "限定SSR命輪免費領取"
  },
  Activity_89729_ActivityName = {
    Text = "支線關卡免費解鎖"
  },
  Activity_89730_ActivityName = {
    Text = "鏡像囚徒"
  },
  Activity_89730_ActivityPlot = {
    Text = "飛鳥啊飛鳥，你的腳上為何有斷裂的鐐銬？\n飛鳥啊飛鳥，你為何在高空之上孤獨地鳴叫？\n掙脫荊棘、逃離囚籠，你展翅飛過了漫漫黃沙，只是你悲傷的鳴叫不曾停止。究竟何人，才是你尋找的忠誠旅伴？究竟何處，才是你尋找的真正家鄉？"
  },
  Activity_89730_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「求知的願望」"
  },
  Activity_89730_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「飛躍青空」、「夢境巡梭」和「成就獎勵」收集活動貨幣「常識之書」、「數理之書」、「文學之書」，「常識之書」、「數理之書」、「文學之書」可在「求知的願望」中購買商品，包括活動限定SR命輪「孤羽」、流明之芯、無垢之芯等。\n2、活動期間，「異夢視界：天邊之外·上」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：卡斯托爾」！\n\n<Title:活動時間>\n1、6 月 2 日 9：00 - 6 月 16 日 9：00（GMT+8），所有活動玩法均可參與。\n2、6 月 16 日 9：00 - 6 月 23 日 9：00（GMT+8），僅可參與「求知的願望」和成就獎勵。\n\n<Title:飛躍青空>\n1、「飛躍青空」包含 7 個關卡，每 1 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 求知的願望>\n「求知的願望」共有三個商店，開啟時間如下：\n·「通識選修課」： 6 月 2 日 9 時開啟。\n·「科學選修課」： 6 月 4 日 9 時開啟。\n·「文學選修課」： 6 月 6 日 9 時開啟。\n在商店內可以選擇商品直接進行購買。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「飛躍青空」關卡任務報酬中的「常識之書」、「數理之書」、「文學之書」獲得額外的掉落加成，具體加成如下：\n·喚醒體「卡斯托爾」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「不可承受的自由」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「孤羽」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title: 夢境巡梭>\n1、每小時自動獲得 60「常識之書」，最多儲存 25 小時。\n\n<Title:異夢視界>\n1、活動期間，「異夢視界：天邊之外·上」可免費解鎖。\n2、活動結束後，「異夢視界：天邊之外·上」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「異夢視界：天邊之外·上」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「異夢視界：天邊之外·上」後都可以獲得「鑰令：錯位命運」。"
  },
  Activity_89730_BannerText = {
    Text = "玩法活動限時開啟！"
  },
  Activity_89899_ActivityName = {
    Text = "幻衣縫製"
  },
  Activity_89899_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可使用「幻視單片鏡」進行抽取。每次抽取所需要的「幻視單片鏡」數量會增加。\n2、銀樞幻衣有機會從第5次抽取開始獲得。完成10次抽取必定獲得當期銀樞幻衣。\n3、活動結束後若有剩餘「幻視單片鏡」將自動轉化為源液。"
  },
  Activity_89899_BannerText = {
    Text = "抽獎活動限時開啟！"
  },
  Activity_90052_ActivityName = {
    Text = "腐壞之腦"
  },
  Activity_90052_ActivityTips = {
    Text = "<Title:活動規則>\n·「腐壞之腦」活動開啟期間，守密人可使用包含「熔毀·朵爾」的系統預設隊伍，無限次體驗指定關卡。\n·體驗活動關卡時，無法調整編隊中的喚醒體。\n<Title:活動獎勵>\n·首次達成關卡挑戰後，可以在活動介面領取試玩獎勵。"
  },
  Activity_90493_ActivityName = {
    Text = "實戰教學"
  },
  Activity_90493_ActivityTips = {
    Text = "活動規則：\n1、守密人可以在對應關卡中學習並練習相關的戰鬥內容。\n2、守密人通關對應實戰教學關卡時，可以在「實戰教學」中領取獎勵。"
  },
  Activity_90861_ActivityName = {
    Text = "共軛命途"
  },
  Activity_90861_ActivityTips = {
    Text = "<Title: 共軛命途>\n·本次限時紀行包含 8 個禮包，其中首個禮包可直接免費領取，第 2-8 個禮包需要購買「共軛命途」後方可領取。\n·購買「共軛命途」後可立即領取第 2 個禮包獎勵；後續禮包需要分別等待一定時間後才可領取。\n·在 4 月 20 日 9：00 前購買「共軛命途」還可額外獲得獎勵：專屬頭像「命運織者」、「無形者的請柬」×10！在 4 月 20 日 9：00 後購買將不再獲得限時專屬獎勵。 \n· 購買後，本次限時紀行的持續時間將會變為永久，當領取完所有的禮包後次日活動關閉。\n·「共軛命途」購買有時間限制，逾期將無法再購買。請守密人在 5 月 18 日 9：00 前酌情購買。"
  },
  Activity_90861_BannerText = {
    Text = "特別紀行活動限時開啟！"
  },
  Activity_90862_ActivityName = {
    Text = "臨時文本"
  },
  Activity_90862_ActivityTips = {
    Text = "<Title: 臨時文本>\n·本次限時預購活動包含 8 個禮包，其中首個禮包可直接免費領取，第 2-8 個禮包需要購買「臨時文本」後方可領取。\n·購買「臨時文本」後可立即領取第 2 個禮包獎勵；後續禮包需要分別等待一定時間後才可領取。\n·「臨時文本」購買有時間限制，逾期將無法再購買。請守密人在4月7日9：00前酌情購買。"
  },
