  Activity_91027_ActivityName = {
    Text = "偉大的征服"
  },
  Activity_91027_ActivityPlot = {
    Text = "一個偉大的時代或許終究會消亡，但那些偉大勇士的意志永遠不會消亡。\n墓碑無法掩埋他們，鎖鏈無法馴服他們。\n當新的征途出現，美味的烤肉在那征服之路的盡頭招手，戰士們發起衝鋒，將那榮耀的戰利品收入囊中。\n讓我們為這不滅的英勇，為這神聖的帝國高歌！\n羅馬！羅馬！"
  },
  Activity_91027_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「敬獻貢禮」"
  },
  Activity_91027_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「神聖的獵食」收集活動貨幣「美味雷歐烤肉」，「美味雷歐烤肉」可在「敬獻貢禮」中購買商品，包括流明之芯、無垢之芯等。\n2、活動期間，「異夢視界：征廚房記」限時免費解鎖。\n\n<Title:活動時間>\n1、6 月 30 日 9：00 - 7 月 21 日 9：00（GMT+8），所有活動玩法均可參與。\n2、7 月 21 日 9：00 - 7 月 28 日 9：00（GMT+8），僅可參與「敬獻貢禮」和成就獎勵。\n\n<Title:神聖的獵食>\n1、「神聖的獵食」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗「靈啡肽」× 120，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 敬獻貢禮>\n在「敬獻貢禮」商店內可以使用活動貨幣「美味雷歐烤肉」選擇商品直接進行購買。\n\n<Title:異夢視界>\n1、活動期間，「異夢視界：征廚房記」可免費解鎖。\n2、活動結束後，「異夢視界：征廚房記」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「異夢視界：征廚房記」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「異夢視界：征廚房記」後都可以獲得「鑰令：獵食決心」。"
  },
