  },
  Activity_95977_ActivityTips = {
    Text = "<Title:活動簡介>\n活動期間，守密人可透過限時玩法「噬靈之饗」和「成就獎勵」收集活動貨幣，活動貨幣可在「王邸餐廳」中用於交換從而獲得道具獎勵，包括活動限定SR命輪「珍饈」、賢者之石、無垢之芯、流明之芯等。\n\n<Title:活動時間>\n1、7 月 21 日 9：00 - 8 月 4 日 9：00（GMT+8），所有活動內容均可參與。\n2、8 月 4 日 9：00 - 8 月 11 日 9：00（GMT+8），僅保留「王邸餐廳」和「成就獎勵」，其他內容均已結束不可參與。\n\n<Title: 噬靈之饗>\n1、「噬靈之饗」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗「靈啡肽」× 120，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地通關。\n\n<Title: 活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「噬靈之饗」關卡任務報酬中的「腐壞手骨」獲得額外的掉落加成（包括重現），具體加成如下：\n·喚醒體「杜勒賽因」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%\n·SSR命輪「安息之吻」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n·SR命輪「珍饈」：疊位0/1/2/3及以上，加成20%/30%/40%/50%\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title: 王邸餐廳>\n1、每次「提交報告」將消耗 750「腐壞手骨」，隨機獲得「王邸餐廳」中的五個物品獎勵。\n2、「王邸餐廳」的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前 5 次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第 6 次及之後重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n3、8 月 11 日 9：00（GMT+8）後，剩餘未兌換的「腐壞手骨」將按照每個兌換「薔薇金券」× 40 的比例進行回收，請守密人注意查收郵件。"
  },
