  Activity_96838_ActivityName = {
    Text = "畫布的暗面"
  },
  Activity_96838_ActivityPlot = {
    Text = "一場色彩的核爆，一次形式的狂亂。\n近乎正常的畫卷，被鮮血的筆觸塗抹，\n刮刀之下，亡魂在畫布的暗面顫慄低語。\n最真實、最完美的藝術就潛藏在瘋癲與荒誕背後，\n唯有撕裂表象的瘋狂，方能窺見世界的裡側。"
  },
  Activity_96838_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「皮克曼的畫室」"
  },
  Activity_96838_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「異界圖卷」、和「成就獎勵」收集活動貨幣「真實之染」、「幻夢之染」、「癲狂之染」，「真實之染」、「幻夢之染」、「癲狂之染」可在「皮克曼的畫室」中購買商品，包括活動限定SR命輪「渴求的畫筆」、流明之芯、無垢之芯等。\n2、活動期間，「意識潛遊：畸世繪」限時免費解鎖，完成活動成就還能獲得活動限定頭像「以銀鑰之名：皮克曼」！\n\n<Title:活動時間>\n1、9 月 8 日 9：00 - 9 月 22 日 9：00（GMT+8），所有活動玩法均可參與。\n2、9 月 22 日 9：00 - 9 月 29 日 9：00（GMT+8），僅可參與「皮克曼的畫室」和成就獎勵。\n\n<Title:異界圖卷>\n1、「異界圖卷」包含 7 個關卡，每 1 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 皮克曼的畫室>\n1、「皮克曼的畫室」共有三個商店，開啟時間如下：\n·「真實畫室」： 9 月 8 日 9 時開啟。\n·「幻夢畫室」： 9 月 10 日 9 時開啟。\n·「癲狂畫室」： 9 月 12 日 9 時開啟。\n2、每次交換將消耗 750「真實之染」/「幻夢之染」/「癲狂之染」，隨機獲得畫室中的五個物品獎勵。\n3、每個畫室的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續交換，當「普通物品」也無剩餘數量後，須進行重置才可以繼續交換。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「異界圖卷」關卡任務報酬中的「真實之染」、「幻夢之染」、「癲狂之染」獲得額外的掉落加成，具體加成如下：\n·喚醒體「皮克曼」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「寫實主義悖謬」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「渴求的畫筆」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title:意識潛遊>\n1、活動期間，「意識潛遊：畸世繪」可免費解鎖。\n2、活動結束後，「意識潛遊：畸世繪」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「意識潛遊：畸世繪」，活動結束後仍然可以消耗「現實起點」×3解鎖。\n3、無論是否在活動期間，通關「意識潛遊：畸世繪」後都可以獲得「鑰令：虛世之彩」。"
  },
