  Activity_97672_ActivityName = {
    Text = "神誕的祭禮"
  },
  Activity_97672_ActivityPlot = {
    Text = "無需再為這華美犧牲品的過往悲泣。\n獻上血與骨，獻上靈與肉，獻上自由，獻上生命。\n她注定尊榮無上，她注定苦痛無依。她是神的女兒，她是神的母親。\n她已欣然接受這可怖又可憎的命運。"
