  Activity_97672_ActivityStageEndContent = {
    Text = "活動已結束，當前僅可參與「創生七日」"
  },
  Activity_97672_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「創生七日」、和「成就獎勵」收集活動貨幣「安神香薰」、「驅魘香薰」、「捕夢香薰」，「安神香薰」、「驅魘香薰」、「捕夢香薰」可在「神母寢宮」中購買商品，包括活動限定SR命輪「藍環毒素」、流明之芯、無垢之芯等。\n2、活動期間完成活動成就還能獲得活動限定頭像「以銀鑰之名：誕妄·墨菲」！\n\n<Title:活動時間>\n1、11 月 24 日 9：00 - 12 月 15 日 9：00（GMT+8），所有活動玩法均可參與。\n2、12 月 15 日 9：00 - 12 月 22 日 9：00（GMT+8），僅可參與「神母寢宮」和成就獎勵。\n\n<Title:創生七日>\n1、「創生七日」包含 7 個關卡，每 1 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title: 褻禱狂歡>\n·活動開始後，每小時自動獲得60「安神香薰」，最多儲存 25 小時。\n\n<Title: 神母寢宮>\n1、「神母寢宮」共有三個商店，開啟時間如下：\n·「異途甜夢」： 11 月 24 日 9 時開啟。\n·「誕神深夢」： 11 月 25 日 9 時開啟。\n·「無望夢魘」： 11 月 26 日 9 時開啟。\n2、每次進奉將消耗 750「安神香薰」/「驅魘香薰」/「捕夢香薰」，隨機獲得寢宮中的五個物品獎勵。\n3、每個寢宮的物品獎勵分為「特殊物品」和「普通物品」兩種，重置時可以使特殊物品獎勵的剩餘數量重置至上限，具體規則為：\n（1）前2次重置：當「特殊物品」無剩餘數量後，守密人可以選擇重置，重置後會將「特殊物品」和「普通物品」的剩餘數量重置至上限；也可以選擇繼續進奉，當「普通物品」也無剩餘數量後，須進行重置才可以繼續進奉。\n（2）第3次開始重置：當「普通物品」無剩餘數量後才可以進行重置，重置會將「普通物品」的剩餘數量重置至上限，「特殊物品」不再重置。\n\n<Title:活動加成>\n1、守密人擁有特定喚醒體或命輪（不要求上陣）可以使「創生七日」關卡任務報酬中的「安神香薰」、「驅魘香薰」、「捕夢香薰」獲得額外的掉落加成，具體加成如下：\n·喚醒體「誕妄·墨菲」：啟靈0/1/2/3及以上，加成20%/30%/40%/50%。\n·SSR命輪「黑暗中的安眠」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n·SR命輪「藍環毒素」：疊位0/1/2/3及以上，加成20%/30%/40%/50%。\n2、不同喚醒體或命輪的「活動加成」以疊加的方式結算。 \n3、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。"
  },
  Activity_97672_BannerText = {
    Text = "玩法活動限時開啟！"
