  Activity_97853_ActivityPlot = {
    Text = "你曾幻想過，如果災難不曾來臨，所有人的生活究竟會是什麼樣子。\n你拯救世界的力量沒有了用武之地， 每天都要為平凡的校園生活和賺取可憐的學分奔波。操場上再也沒有了訓練作戰的身影，取而代之的是一排排社團活動的帆布棚子，與招攬、嬉鬧的叫嚷聲；待放學的鐘聲敲響，飢餓的學生們便立刻擠滿了食堂……\n敲開你牽掛著的人們的房門，你會看到怎樣的笑臉？"
