  Activity_97853_ActivityTips = {
    Text = "<Title:活動簡介>\n1、活動期間，守密人可透過限時玩法「日光下新事」收集活動貨幣「海濱特產貝殼」，「海濱特產貝殼」可在「學生會辦公樓」中購買商品，包括流明之芯、無垢之芯、賢石碎屑等。\n2、活動期間，「異夢視界：再見，永無鄉」限時免費解鎖！\n\n<Title:活動時間>\n1、10 月 6 日 9：00 - 10 月 20 日 9：00（GMT+8），所有活動玩法均可參與。\n2、10 月 20 日 9：00 - 10 月 27 日 9：00（GMT+8），僅可參與「學生會辦公樓」和成就獎勵。\n\n<Title:日光下新事>\n1、「日光下新事」包含 5 個關卡，每 2 天自動開放 1 個。\n2、每次挑戰將消耗 「靈啡肽」× 120 ，挑戰成功將獲得活動貨幣。\n3、關卡通關後，解鎖該關卡的「重現」功能。請注意：使用「重現」功能時，無法獲得同調率。\n4、可以使用校友會助戰來幫助你更輕鬆地過關。\n\n<Title:活動加成>\n1、解鎖「假日紀行」中的「高級紀行」，可在「日光下新事」關卡報酬中獲得額外100%的「海濱特產貝殼」掉落（包括重現）。\n2、特別的，癲狂難度首通挑戰獎勵不會受到「活動加成」影響。\n\n<Title: 學生會辦公樓>\n「學生會辦公樓」共有一個商店， 10 月 6 日 9 時開啟。\n在商店內可以選擇商品直接進行購買。\n\n<Title:異夢視界>\n1、活動期間，「異夢視界：再見，永無鄉」可免費解鎖。\n2、活動結束後，「異夢視界：再見，永無鄉」的調查進度會保留，完成活動期間未完成的調查事件後也可以獲得與活動期間一致的調查獎勵。如果活動期間未解鎖「異夢視界：再見，永無鄉」，活動結束後仍然可以消耗「現實起點」×7解鎖。\n3、無論是否在活動期間，通關「異夢視界：再見，永無鄉」後都可以獲得「鑰令：美夢一剎」。"
  },
